SELECT 'moj-all-verified-judgments-review-002-chunk-002' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d70ee2bf-cc13-5a00-8c9c-60edcfa8f41f","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -املطالبة بإعادة قيمة تذاكر -عدم حضور املدعى عليه - احلكم غيابي ا بإعادة ثمن التذاكر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33152564","case_number":"8603","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/26","year":"1434","subject":"بيع -املطالبة بإعادة قيمة تذاكر -عدم حضور املدعى عليه - احلكم غيابي ا بإعادة ثمن التذاكر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/3/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33152564 :‬‬\n                        ‫َر ْق ُم الدعوى‪8603 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34229126‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n‫بيــع ‪ -‬املطالبــة بإعــادة قيمــة تذاكــر‪ -‬عــدم حضــور املدعــى عليــه ‪-‬‬\n‫احلكــم غيابيـ ًا بإعــادة ثمــن التذاكــر ‪ -‬رفــع احلكــم حملكمة االســتئناف‬\n                                  ‫لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n                  ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بأنــه مت إيــداع مبلــغ مالــي يف حســاب املدعــى‬\n‫عليــه قيمــة تذاكــر ســفر ‪ -‬لــم يتــم تســليم هــذه التذاكــر ‪ -‬طلــب‬\n‫املدعــي احلكــم غيابي ـ ًا علــى املدعــى عليــه بإعــادة املبلــغ املذكــور‬\n‫قيمــة التذاكــر ‪ -‬قامــت احملكمــة باالســتيثاق مــن اإليــداع عــن طريــق‬\n‫ا بنكيـ ًا‬‫مؤسســة النقــد ‪ -‬كمــا أن املدعــي قــدم لصحــة دعــواه حتويـ ً‬\n‫وقــام بحلــف اليمــن ‪ -‬لــذا حكمــت احملكمــة غيابي ـ ًا بإلــزام املدعــى‬\n‫عليــه بدفــع قيمــة تذاكــر الســفر املودعــة ‪ -‬الغائــب علــى حجتــه متــى‬\n                        ‫حضــر ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                ‫‪82‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 8603‬وتاريــخ ‪ 1429/02/18‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 2925769‬وتاريــخ ‪ 1429/02/18‬ه ـ ففــي يــوم األحــد‬\n     ‫املوافق‪ 1432/10/13‬هـ افتتحت اجللسة الساعة ‪ 12 : 57‬وفيها حضر‬\n     ‫‪ .............‬ســجل رقــم ‪ .............‬بالوكالــة عــن ‪ ...........‬بالوكالــة رقــم‬\n     ‫‪ 9484‬يف ‪ 1429/01/25‬ه ـ الصــادرة مــن كتابــة العدل الثانية يف شــرق‬\n     ‫الريــاض ولــم يحضــر املدعــى عليــه ‪ ...........‬ســجل رقــم ‪1001661253‬‬\n     ‫وقــد جــرى تبليغــه عــن طريــق وزارة الداخليــة باخلطاب رقــم‪321158565‬‬\n     ‫وقــد جــرى حتديــد موعــد جديــد يــوم األحــد املوافــق ‪ 1432/11/25‬ه ـ‬\n     ‫ويف يــوم الثالثــاء املوافــق ‪ 1432/11/27‬ه ـ حضــر املدعــي وكالــة ولــم‬\n     ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وبســؤال املدعــي عــن دعــواه قــال‬\n     ‫إنــه يف تاريــخ ‪ 2007/04/14‬مت إيــداع مبلــغ ثالثمائــة وثمانيــة وخمســن‬\n     ‫ألفــا وأربعمائــة وثمانيــة وثمانــن ريــاال يف حســابه وذلــك قيمــة تذاكــر‬\n     ‫ســفر ولــم يتــم تســليم موكلــي هــذه التذاكــر حيــث أنــه اختفــى ونظــرا‬\n     ‫ألن فضيلتكــم طلــب مــن مؤسســة النقــد التأكــد مــن صحــة اإليــداع‬\n     ‫ومت ذلــك وحيــث أننــا تعبنــا مــن املراجعــة والبحــث عنــه أكثــر مــن ثــاث‬\n     ‫ســنوات دون العثــور عليــه ومت حتديــد ثــاث جلســات دون حضــوره لــذا‬\n     ‫أطلــب مــن فضيلتكــم احلكــم علــى املدعــى عليــه باملبلــغ املدعــى بــه‬\n     ‫غيابيــا هكــذا ادعــى وبســؤاله البينــة علــى دعــواه قــال لــدي البينــة‬\n     ‫وســوف أحضرهــا يف اجللســة القادمــة وعليــه رفعــت اجللســة وحــدد لهــا‬\n\n‫‪83‬‬\n\f‫موعــد يــوم االثنــن املوافــق ‪ 1433/01/24‬ه ـ ويف يــوم االثنــن املوافــق‬\n‫‪ 1433/01/24‬ه ـ حضــر املدعــي وكالــة وبســؤاله عــن البينــة التــي وعد‬\n‫بهــا أبــرز طلــب حتويــل علــى ‪ .........‬بتاريــخ ‪ 2007/04/14‬مببلــغ وقــدره‬\n‫ثالثمائــة وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال وقــال‬\n‫إن هــذه هــي بينتــي وال يوجــد لــدى موكلــي بينــة أخــرى وقــد جــرى‬\n‫االستفســار عــن هــذه احلوالــة فوردنــا خطــاب مؤسســة النقــد رقــم ‪1508‬‬\n‫ن ظ ‪ /‬أ ق يف ‪ 1432/07/06‬هـ واملتضمن أن احلوالة صحيحة وصادرة‬\n‫مــن حســاب املدعــي لصالــح حســاب املدعــى عليه بتاريــخ ‪2007/04/14‬‬\n‫ا‪.‬ه ـ عنــد ذلــك طلبــت مــن املدعــي إحضــار موكلــه يف اجللســة القادمــة‬\n‫ألداء اليمــن علــى صحــة دعــواه فاســتعد بذلــك وعليــه رفعــت اجللســة‬\n‫وحــدد لهــا موعــد يــوم األربعــاء ‪1433/03/23‬ه ـ ويف يــوم األربعــاء‬\n‫املوافــق‪ 1433/03/23‬ه ـ حضــر املدعــي وكالــة وحضــر حلضــوره‬\n‫املدعــي أصالــة ‪ ............‬ســجل رقــم ‪ .........‬وبعــرض اليمــن عليــه حلــف‬\n‫قائــا واهلل العظيــم إننــي حولــت للمدعــى عليــه ‪ ..............‬مبلغــا وقــدره‬\n‫ثالثمائــة وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال يف‬\n‫حســابه وذلــك قيمــة تذاكــر ســفر ولكنــه لــم يســلم لــي التذاكــر حتــى‬\n‫اآلن ولــم يعــد لــي املبلــغ وال جــزءا منــه واهلل هكــذا حلــف فبنــاء علــى مــا‬\n‫ســبق مــن الدعــوى وخطــاب مؤسســة النقــد وحلــف املدعــي اليمــن طبــق‬\n‫مــا طلــب منــه لــذا فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره ثالثمائــة‬\n‫وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال للمدعــي‬\n‫وبذلــك حكمــت وهــو حكــم غيابــي خاضــع لتعليمــات التمييــز والغائب‬\n‫علــى حجتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/03/23‬ه ـ‬\n\n\n                                                                                        ‫‪84‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n     ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n     ‫من فضيلة رئيس احملكمة العامة بالرياض املساعد برقم ‪32624884‬‬\n     ‫وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n     ‫باحملكمــة الشــيخ‪ ................./‬املســجل برقــم ‪ 33152564‬وتاريــخ‬\n     ‫‪1433/3/26‬ه ـ اخلــاص بدعوى‪........./‬وكالــة ضــد‪.........../‬يف مبلــغ من‬\n     ‫املــال علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم فضيلتــه كمــا‬\n     ‫هــو موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم‬\n     ‫يظهــر مــا يوجــب االعتــراض علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪85‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":82,"source_page_end":85,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"45241451d8e795fdc2ef63dfc1acf58cc323ec8a07626385cc5f9100a2b17c8a","normalized_text_hash":"e6187a74f941c120fc7f2da2c2f6fbc5ac8bb23e5ae4a4ae65a292766a080f11","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p82-33152564"},{"id":"5440111b-2f01-56b1-b98b-d207781b7386","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عربون -دفع للوسيط كداللة مقابل التوسط يف شراء فيا -الرجوع يف الشراء -املطالبة برد مبلغ الداللة -رفض رد املبلغ -املبلغ املدفوع عربون وليس داللة -مصادقة املدعي على السند املرفق باملعاملة بأن املبلغ عربون -رد دعوى املدعي وإخاء سبيل املدعى عليه من الدعوى .","document_number":"34229820","case_number":"31922","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"بيع -عربون -دفع للوسيط كداللة مقابل التوسط يف شراء فيا -الرجوع يف الشراء -املطالبة برد مبلغ الداللة -رفض رد املبلغ -املبلغ املدفوع عربون وليس داللة -مصادقة املدعي على السند املرفق باملعاملة بأن املبلغ عربون -رد دعوى املدعي وإخاء سبيل املدعى عليه من الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34229820 :‬‬\n                      ‫َر ْق ُم الدعوى‪31922 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34331655‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n‫بيــع ‪ -‬عربــون ‪ -‬دفــع للوســيط كداللــة مقابــل التوســط يف شــراء فيــا‬\n‫‪ -‬الرجــوع يف الشــراء ‪ -‬املطالبــة بــرد مبلــغ الداللــة ‪ -‬رفــض رد املبلــغ‬\n‫‪ -‬املبلــغ املدفــوع عربــون وليــس داللــة ‪ -‬مصادقــة املدعــي علــى الســند‬\n‫املرفــق باملعاملــة بــأن املبلــغ عربــون ‪ -‬رد دعــوى املدعــي وإخــاء ســبيل‬\n                                                ‫املدعــى عليــه مــن الدعــوى ‪.‬‬\n\n\n\n                            ‫‪ -1‬قوله تعالى (بل اإلنسان على نفسه بصيرة) ‪.‬‬\n                                              ‫‪ -2‬قاعدة ‪ :‬ال عذر ملن ّأقر ‪.‬‬\n\n\n\n‫قــام املدعــي بدفــع مبلــغ داللــة إلــى املدعــى عليــه مقابــل وســاطته يف‬\n‫شــراء فيــا لــه‪ ،‬طلــب املدعــي مــن املدعــى عليــه تخفيــض ثمــن الفيــا‬\n‫لوجــود إصالحــات جوهريــة بهــا‪ ،‬رفــض املدعــى عليــه ذلــك بحجــة أن‬\n‫املبلــغ املدفــوع عربــون وليــس مقابــل داللــة وقــد ســلمه للمالــك‪ ،‬وقــدم‬\n‫ا علــى ذلــك ســند القبــض مبينـ ًا بــه أن املبلــغ املدفــوع‬ ‫املدعــى عليــه دليـ ً‬\n‫عربون ـ ًا للشــراء‪ ،‬أقّ ــر املدعــي بصحــة الســند إال أنــه لــم ينتبــه إلــى مــا‬\n‫وجــد بــه‪ ،‬حكمــت احملكمــة بــرد الدعــوى واخــاء ســبيل املدعــى‬\n‫عليــه مــن الدعــوى ‪ -‬اعتــرض املدعــي ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                       ‫االســتئناف ‪.‬‬\n                                                                                         ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض املســاعد برقــم ‪ 31922‬وتاريــخ ‪1431/07/04‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 31123171‬وتاريــخ ‪1431/07/04‬ه ـ ففــي‬\n     ‫يــوم األربعــاء املوافــق ‪1433/10/25‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n     ‫‪ 08‬وفيهــا حضــر ‪ .........‬مبوجــب ســجل مدنــي رقــم ‪ ...........‬وادعــى علــى‬\n     ‫احلاضــر معــه ‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...............‬بصفتــه‬\n     ‫وكيــا عــن‪ .........‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...........‬ينــوب عنــه‬\n     ‫يف املطالبــة واملرافعــة واملدافعــة واإلنــكار واإلقــرار والصلــح وقبــول‬\n     ‫األحــكام ونفيهــا مبوجــب صــك وكالــة صــادر مــن كتابــة العــدل‬\n     ‫الثانيــة بشــرق الريــاض رقــم ‪ 33317217‬يف‪1433/10/18‬ه ـ قائــا يف‬\n     ‫حتريــر دعــواه عليــه ســبق أن اشــتريت مــن ‪.............‬فيــا يف حــي احلمــراء‬\n     ‫وكان املدعــى عليــه وســيطا بينــي وبينــه وســلمت املدعــى عليــه شــيكا‬\n     ‫باســمه مببلــغ وقــدره خمســة وســبعون ألــف ريــال للداللــة وبعــد ذلــك‬\n     ‫طلبــت مــن املدعــى عليــه تخفيــض قيمــة الفيــا ألن فيهــا أشــياء جوهريــة‬\n     ‫حتتــاج إلــى مبالــغ طائلــة لتعديلهــا فأخبرنــي بــأن املالــك رفــض ذلــك‬\n     ‫فطلبــت منــه إرجــاع مبلــغ الداللــة فرفــض أطلــب إلزامــه بإرجاعــه هــذه‬\n     ‫دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n     ‫مــن أن موكلــي كان وســيط يف بيــع الفيــا وأنــه اســتلم منــه املبلــغ‬\n     ‫املذكــور فصحيــح إال أن املبلــغ كان عربونــا لشــراء الفيــا وقــد اســتلم‬\n     ‫صاحــب العقــار العربــون وقــد ســبق أن صــدر صــك مــن ديــوان املظالــم‬\n\n‫‪87‬‬\n\f‫بصــرف النظــر عــن دعــوى املدعــي والتــي ادعــى فيهــا أن املبلــغ الــذي‬\n‫دفعــه لنــا كان عربــون لــذا أطلــب صــرف النظــر عــن دعــوى املدعــي‬\n‫هكــذا أجــاب ثــم أبــرز املدعــى عليــه صــورة ســند قبــض علــى مطبوعات‬\n‫شــركة ‪ .................‬املتضمــن اســتالم املبلــغ املذكــور مــن املدعــي‬\n‫وذلــك عــن قيمــة عربــون شــراء فيــا باحلمــراء لقيمــة ثالثــة مليــون ريــال‬\n‫مســاحة ‪1125‬م ثــم أبــرز ورقــة عاديــة موقــع عليهــا مــن قبــل ‪..............‬‬\n‫تتضمــن اســتالمه للمبلــغ مــن املدعــى عليــه ثــم أبــرز صــورة احلكــم رقــم‬\n‫‪/60‬د‪/‬ف‪ 2/‬لعــام ‪ 1431‬الصــادر مــن ديــوان املظالــم فوجدتــه مطابقــا‬\n‫ملــا ذكــر وبســؤال املدعــي هــل لديــه بينــة علــى أن املبلــغ املذكــور‬\n‫داللــة أجــاب قائــا ليــس لــدي بينــة ســوى أن مبلــغ يســاوي قيمــة الداللــة‬\n‫املتعــارف عليهــا يف الســوق هكــذا أجــاب وبعــرض ميــن املدعــى عليــه‬\n‫أصالــة علــى املدعــي قبــل بهــا لــذا أمــرت بطلــب حضــور املدعــى عليــه‬\n                                                               ‫أصالــة ألداء اليمــن‬\n‫ويف جلســة أخــرى حضــر املدعــي واملدعــى عليــه أصالة ‪ .............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬وبســؤال املدعــى عليــه‬\n‫أصالــة عمــا ذكــره املدعــي أصالــة مــن أنهــا عربــون للفلــة وليســت ســعي‬\n‫قــال‪ :‬أنهــا عربــون وقــد ســلمت صاحــب الفيــا هــذا العربــون وبقيــت‬\n‫الفيــا ملــدة شــهرين لــم تبــاع وحــن تأخــر املدعــي عــن دفــع قيمــة الفيــا‬\n‫قــام صاحــب الفيــا ببيعهــا وقــد ســلمت صاحــب الفيــا املبلــغ بنــاء علــى‬\n‫ســند صــرف رقــم ‪ 157‬والــذي دفعــت لــه مبوجبــه هــذا املبلــغ هكــذا‬\n‫أجــاب؛ لــذا طلبــت إدخــال صاحــب الفيــا ‪ .......................‬يف الدعــوى‬\n‫ويف جلســة أخــرى لــدي أنــا ‪............‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم األحــد املوافــق‪ 1434/06/04‬ه ـ افتتحــت اجللســة‬\n\n\n                                                                                       ‫‪88‬‬\n\f     ‫الســاعة ‪ 09.30‬وفيهــا حضــر املدعــي اصالــة واملدعــى عليــه وكالــة‬\n                           ‫‪ ........‬املــدون هوياتهمــا ووكالــة املدعــى عليــه ســابقا‬\n     ‫وبتــاوة مــا جــرى ضبطــه صادقــا عليــه وبســؤال املدعــي اصالــة عن ســند‬\n     ‫القبــض رقــم ‪ 0050‬يف ‪1430/11/20‬ه ـ واملرفــق نســخة منــه باملعاملــة‬\n     ‫قــال هــذا الســند هــو الــذي ســلم لــي وهــو مطابــق ملــا لديكــم وباالطــاع‬\n     ‫عليــه وجدتــه متضمنــا مــا نصــه ‪ ( :‬وذلــك قيمــة عربــون شــراء فيــا‬\n     ‫باحلمــراء بقيمــة ‪ 3.000.000‬ثالثــة مليــون ريــال مســاحة ‪1125‬م ) أ‪.‬ه ـ‬\n     ‫وبعرضــه علــى املدعــي وهــو أكادميــي يف جامعــة امللــك ســعود يحمــل‬\n     ‫شــهادة الدكتــوراه أجــاب بقولــه لــم انتبــه ملــا كتــب يف الســند وأنــا قليــل‬\n     ‫خبــرة يف مثــل هــذه األمــور علمــا انــه هــو الــذي كتــب محتــوى الســند‬\n     ‫هــذه إجابتــي وبعــد االطــاع علــى مــا ســبق ضبطــه من الدعــوى واإلجابة‬\n     ‫واإلقــرار املدعــي بصحــة الســند وال عــذر ملــن أقــر ولعمــوم قولــه تعالــى‬\n     ‫( بــل اإلنســان علــى نفســه بصيــرة ) وملشــروعية بيــع العربــون بــأن يقــول‬\n     ‫ـزاء مــن قيمــة املبيــع فــإن أتيتــك بباقــي القيمــة‬‫املشــتري للبائــع خــذ جـ ً‬\n     ‫وإال فهــو لــك وألن املفــرط أولــى باخلســارة ولــم احتــج ميــن املدعــى عليــه‬\n     ‫اصالــة علــى إنــكار الدعــوى لعــدم وجــود احلاجــة إليــه بعــد مصادقــة‬\n     ‫املدعــي علــى الســند املرفــق باملعاملــة وجلميــع مــا تقــدم فقــد حكمــت‬\n     ‫بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‬\n     ‫وبعرضــه علــى املدعــي قــرر عــدم القناعــة فجــرى تســليمه نســخة مــن‬\n     ‫إعــام احلكــم وأفهمتــه بــأن لــه إبــداء اعترضــه عليــه خــال ثالثــن‬\n     ‫يومـ ًا مــن تاريــخ اســتالم نســخة احلكــم تنتهــي يف ‪1434/07/04‬ه ـ فــإن‬\n     ‫مضــت املــدة دون تقــدمي الالئحــة االعتراضيــة ســقط حقــه يف االعتــراض‬\n     ‫واكتســب احلكــم القطعيــة وذلــك اســتناد ًا للمــواد رقــم ‪176‬و‪ 178‬مــن‬\n\n\n‫‪89‬‬\n\f                ‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ففهــم ذلــك‬\n‫أمــا املدعــى عليــه فلــم يتــم عــرض احلكــم عليــه اســتنادا للمــادة ‪147‬‬\n‫مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/04‬ه ـ والســاعة‬\n                                                                     ‫‪. 10.00‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34331655‬وتاريــخ‬\n                                              ‫‪1434/10/15‬هـ‪.‬‬\n\n\n\n\n                                                                                   ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":86,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9e3cda29e6b606d8c9641396956d784e378a3fd92f7503b36f5acde38d33a610","normalized_text_hash":"89ad6df4ab9016a21a21e743226400088d5ba15d398ea2e1e098f7ce681aa34a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p86-34229820"},{"id":"8a3c1390-f5c1-5d18-93e8-f14a36cc389b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع فيا وعدم قبض كامل الثمن -بينة املدعي صك سابق بأحقيته يف املبلغ -إلزام املدعى عليه بدفع الثمن .","document_number":"33192371","case_number":"34173","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/14","year":"1434","subject":"بيع -بيع فيا وعدم قبض كامل الثمن -بينة املدعي صك سابق بأحقيته يف املبلغ -إلزام املدعى عليه بدفع الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/4/14 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33192371 :‬‬\n                           ‫َر ْق ُم الدعوى‪34173 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3410470‬تاريخه‪1434/1/12 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬بيــع فيــا وعــدم قبــض كامــل الثمــن ‪ -‬بينــة املدعــي صــك‬\n           ‫ســابق بأحقيتــه يف املبلــغ ‪ -‬إلــزام املدعــى عليــه بدفــع الثمــن ‪.‬‬\n\n\n\n\n                       ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه اشــترى منــه فيــا‪ ،‬قــام املدعــى عليــه‬\n     ‫بســداد جــزء مــن املبلــغ‪ ،‬طالــب املدعــي إلــزام املدعــى عليــه بســداد باقــي‬\n     ‫الثمــن ‪ ،‬دفــع املدعــى عليــه بســداد كامــل الثمــن‪ ،‬قــام املدعــي بإبــراز‬\n     ‫صــك ســابق علــى موضــوع الدعــوى يفيــد بــأن املبلــغ محــل اخلــاف مــن‬\n     ‫حــق املدعــي ‪ -‬لــذا فقــد ثبــت أن بذمــة املدعــى عليــه للمدعــي مبلــغ مائتي‬\n     ‫ألــف ريــال وألزمتــه بســدادها وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n                    ‫عــدم القناعــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪97‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 43173‬وتاريــخ ‪1431/10/12‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 31169092‬وتاريــخ ‪1431/10/12‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق ‪1433/01/08‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 13‬‬\n‫وقــد ســبق وأن حــدد لهمــا موعــد يــوم األربعــاء ‪1432/02/08‬ه ـ الســاعة‬\n‫‪ 10 : 30‬ثــم حــدد لهمــا موعــد يــوم األحــد ‪1432/06/05‬ه ـ الســاعة ‪30‬‬\n‫‪ 09 :‬ثــم حــدد لهمــا موعــد يــوم األحــد ‪1432/07/10‬ه ـ الســاعة ‪: 15‬‬\n‫‪ 10‬ثــم حــدد لهمــا موعــد هــذا اليــوم ‪1433/01/08‬ه ـ الســاعة ‪10 : 00‬‬\n‫ولــم يســتلم املدعــى عليــه التبليــغ إال التبليــغ لهــذه اجللســة وأول جلســة‬\n‫ويف هــذا اليــوم حضــر ‪ ............‬ســجل مدنــي رقــم ‪ ........‬وادعــى علــى‬\n‫ا يف دعــواه عليــه ‪:‬‬‫احلاضــر معــه ‪ .............‬ســجل مدنــي رقــم ‪ ...........‬قائـ ً‬\n‫لقــد اشــترى املدعــى عليــه منــي الفيــا الواقعــة يف حــي املنــار واململوكــة‬\n‫بالصــك رقــم ‪ 510108004257‬مببلــغ قــدره مليــون وســتمائة ألــف ريــال‬\n‫بتاريــخ ‪1428/02/20‬ه ـ ســلم مــن القيمــة مبلــغ قــدره مليــون وأربعمائــة‬\n‫ألــف ريــال وبقــي مبلــغ قــدره مائتــان ألــف ريــال لــم يســلمها أطلــب احلكــم‬\n‫علــى املدعــى عليــه بدفــع هــذا املبلــغ لــي هــذه دعــواي وبعرضهــا علــى‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬أطلــب مهلــة لإلجابــة وأجيــب لطلبــه ويف‬\n‫جلســة أخــرى لــدي أنــا ‪ ...............‬القاضــي باحملكمــة العامــة بالريــاض‬\n‫ففــي يــوم األربعــاء املوافــق ‪1433/04/14‬ه ـ فتحــت اجللســة الســاعة‬\n‫‪ 12 : 00‬وقــد انتقــل فضيلــة القاضــي ناظــر القضيــة الســابق عــن‬\n\n                                                                                          ‫‪98‬‬\n\f     ‫العمــل بهــذه احملكمــة وجــرى تكليفنــا بالعمــل بهــذا املكتــب وقــررت‬\n     ‫إكمــال نظــر الدعــوى اســتناد ًا للمــادة (‪ )166‬مــن نظــام املرافعــات هــذا‬\n     ‫وقــد حضــر يف هــذه اجللســة املدعــي أصالــة واملدعــى عليــه أصالــة وجــرى‬\n     ‫عــرض الدعــوى علــى املدعــي فأقــر بــأن هــذه دعــواه وبعــرض الدعــوى‬\n     ‫علــى املدعــى عليــه قــال ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن أننــي اشــتريت‬\n     ‫منــه املنــزل املذكــور بالثمــن املذكــور فهــذا كلــه صحيــح وأمــا مــا‬\n     ‫ذكــره مــن الواصــل فهــو غيــر صحيــح والصحيــح أننــي ســلمت الثمــن‬\n     ‫ا وليــس يف ذمتــي للمدعــي أي مبلــغ هكــذا أجــاب وبعــرض ذلــك‬        ‫كامـ ً‬\n     ‫علــى املدعــي قــال‪ :‬الصحيــح مــا ذكــرت وبســؤال املدعــى عليــه عــن‬\n     ‫البينــة علــى التســليم قــال ‪ :‬بينتــي ضبــط املبايعــة لــدى كتابــة العــدل‬\n     ‫حيــث قــرر املدعــي أنــه اســتلم كامــل الثمــن هكــذا قــال وبعــرض ذلــك‬\n     ‫علــى املدعــي قــال ‪ :‬مــا ذكــره صحيــح ولكــن كان إقــرار ًا صوري ـ ًا‬\n     ‫بخصــوص الثمــن مــن أجــل اإلفــراغ وقــد أقــام املدعــى عليــه دعــوى بعــد‬\n     ‫املبايعــة يطالبنــي فيهــا بقيمــة األثــاث الــذي كان موجــود ًا يف املنــزل‬\n     ‫وقــت املبايعــة يدعــي فيهــا بأنــه مــن ضمــن املبايعــة وقــد ذكــر يف دعــواه‬\n     ‫أنــه لــم يســلم مــن الثمــن إال املبلــغ الــذي ذكــرت وهــذه الدعــوى الحقــة‬\n     ‫باإلفــراغ ممــا يــدل علــى أن إقــراري باســتالم كامــل الثمــن كان إقــرار ًا‬\n     ‫صوريـ ًا وقــد انتهــت الدعــوى باحلكــم الصــادر مــن هــذه احملكمــة برقــم‬\n     ‫‪ 17/43‬وتاريــخ ‪1430/11/23‬ه ـ ‪ ،‬وختمــت اجللســة لضيــق الوقــت‬\n     ‫حلضــور وقــت الصــاة ‪ ،‬وختمــت اجللســة الســاعة ‪ ، 12 : 15‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وبعــد أداء الصــاة مــن نفــس اليــوم فتحــت اجللســة وحضــر‬\n     ‫فيهــا املدعــي واملدعــى عليــه و أبــرز املدعــي صــك احلكــم الصادر املشــار‬\n     ‫إليــه وقــد جــاء يف دعــوى وكيــل املدعــي مــا نصــه «لقــد اشــترى موكلــي‬\n\n\n‫‪99‬‬\n\f‫مــن املدعــى عليــه الفلــه الواقعــة بحــي املنــار بالريــاض مببلــغ قــدره مليــون‬\n‫وســتمائة ألــف ريــال ومعهــا كامــل األثــاث املوجــود يف الفلــه مــا عــد‬\n‫غــرف النــوم علــى أن يكــون اســتالم الفلــه يف ‪1428/06/17‬ه ـ وقــد مت‬\n‫إفــراغ الصــك إلــى موكلــي مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n‫الريــاض برقــم ‪ 510108004257‬وســلم موكلــي للمدعــى عليــه عنــد‬\n‫إفراغهــا مليــون وأربعمائــة ألــف ريــال وقــد ســلم قبــل ذلــك مبلــغ قــدره‬\n‫مائتــا ألــف ريــال للمدعــى عليــه يف عــام ‪1427‬ه ـ عندمــا أراد أن يشــتري‬\n‫الفلــه يف هــذا العــام وبعــد أن عجــز موكلــي عــن دفــع كامــل املبلــغ قــرر‬\n‫االتفــاق الــذي تضمــن بيــع املدعــى عليــه ملوكلــي الفلــه مببلــغ مليــون‬\n                                                ‫وســتمائة ألــف مــع األثــاث» إ‪.‬ه ـ‬\n‫كمــا وجــدت مــن ضمــن الدفوعــات اخلــاف علــى مبلــغ مائتــي ألــف‬\n‫ريــال والــذي ســلمه املدعــى عليــه كعربــون يف اتفــاق ســابق علــى شــراء‬\n‫البيــت محــل الدعــوى حســب إفــادة املدعــي فســألت املدعــى عليــه هــل‬\n‫هــذا املبلــغ املذكــور يف الصــك هــو مــن ضمــن الواصــل الــذي يذكــره‬\n‫قــال ‪ :‬نعــم إنــه مــن ضمــن الواصــل هــذا وقــد تضمــن الصــك املذكــور‬\n‫قــول فضيلــة ســلفنا مــا نصــه «وبعــرض اليمــن علــى املدعــى عليــه اســتعد‬\n‫ا ‪ :‬واهلل العظيــم الــذي ال إلــه غيــره أن مبلــغ املائتي‬\n                                                          ‫بأدائهــا ثــم حلــف قائـ ً‬\n‫ألــف املدفوعــة قبــل االتفاقيــة غيــر داخلــة ضمــن مبلــغ االتفاقيــة احملــررة‬\n‫ـاء عليــه فقــد ثبــت لــدي ذلــك» إ‪.‬ه ـ‬‫يف عــام ‪1428‬ه ـ هكــذا حلــف فبنـ ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬  ‫‪ ،‬فبنـ ً‬\n‫بشــرائه للمنــزل املذكــور بالثمــن املذكــور وأنكــر الواصــل ودفــع بأنــه‬\n‫قــد ســلم كامــل القيمــة وحيــث قــرر املدعــى عليــه أن مــن ضمــن املبلــغ‬\n‫الواصــل الــذي يذكــره مبلــغ مائتــي ألــف ريــال وأنــه هــو املبلــغ الــذي‬\n\n\n                                                                                         ‫‪100‬‬\n\f      ‫حصــل فيــه اخلــاف بــن الطرفــن يف القضيــة احملكــوم بهــا يف الصــك‬\n      ‫املشــار إليــه أعــاه ونظــر ًا ملــا قــرره فضيلــة مصــدر الصــك مــن أن ذلــك‬\n      ‫املبلــغ لــم يكــن مــن ضمــن مبلــغ االتفاقيــة والتــي تضمنــت عقــد املبايعــة‬\n      ‫بــن الطرفــن لــذا فقــد ثبــت لــدي أن بذمــة املدعــى عليــه للمدعــي مبلــغ‬\n      ‫مائتــي ألــف ريــال وألزمتــه بســدادها وحكمــت بذلــك وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة‬\n      ‫االســتئناف فجــرى تســليمه نســخة مــن احلكــم وأفهــم بــأن عليــه تقــدمي‬\n      ‫الالئحــة االعتراضيــة خــال املــدة احملــددة ‪ ،‬وختمــت اجللســة الســاعة‬\n      ‫‪ ، 01 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪1433/04/14‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1433/0 1/09‬ه ـ‬\n      ‫فتحــت اجللســة الســاعة العاشــرة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالريــاض وبرفقهــا القــرار رقــم ‪ 33308070‬وتاريــخ‬\n      ‫‪1433/06/21‬ه ـ واملتضمــن أنــه لوحــظ مــا يلــي ‪ ( :‬أوال ذكــر املدعــي‬\n      ‫يف الصــك الســابق رقــم ‪ 17/43‬عنــد جوابــه علــى الدعوى املرفوعة ضده‬\n      ‫حــول األثــاث أن هــذا املبلــغ مقابــل األثــاث الــذي لــم يســلمه وهــذا إقــرار‬\n      ‫صريــح مؤاخــذ بــه فعلــى فضيلتــه مناقشــته مع طريف الدعــوى وإجراء ما‬\n      ‫يلــزم نحــوه ثانيــا ‪ :‬لــم يرفــق فضيلتــه صــورة مــن صــك اإلفــراغ ولــم يجــري‬\n      ‫اإليجــاب الشــرعي نحــو مــا دفــع بــه املدعــى عليــه مــن إقــرار املدعــي‬\n      ‫باســتالم كامــل القيمــة والبــد مــن ذلــك فعلــى فضيلتــه مالحظــه مــا‬\n      ‫ذكــر ) أ‪.‬ه ـ نصــه وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة بخصــوص‬\n      ‫امللحوظــة الثانيــة نقــول أنــه مت إجــراء اإليجــاب الشــرعي حســب مــا‬\n      ‫يتضــح مــن وقائــع املرافعــة وقــد أقــر بــه املدعــي إال أنــه دفــع بــأن ذلــك‬\n\n\n‫‪101‬‬\n\f‫اإلقــرار باســتالم القيمــة كان إقــرار صوريــا وأن بينتــه هــي دعــوى‬\n‫املدعــى عليــه بعــد ذلــك أمــا بخصــوص امللحوظــة األولــى فقــد حضــر‬\n‫يف هــذه اجللســة املدعــي كمــا حضــر ‪ ........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن املدعــى عليــه مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل شــرق الريــاض الثانيــة برقــم ‪33282059‬‬\n‫وتاريــخ ‪1433/09/23‬ه ـ وبعــرض مــا جــاء يف الصــك الســابق مــن إقــرار‬\n‫املدعــي بــأن املبلــغ الباقــي هــو مقابــل األثــاث عليــه والــذي أشــار إليــه‬\n‫أصحــاب الفضيلــة فقــال إن مــا ذكرتــه هــو حكايــة عــن مــا قالــه‬\n‫املدعــى عليــه لــي وليــس علــى ســبيل املوافقــة عليــه هكــذا قــال وبعــد‬\n‫الرجــوع إلــى نــص كالم املدعــي املشــار إليــه وجــدت أنــه ممــا يــدل علــى‬\n‫صحــة مــا ذكــره مــن أن ذكــره لذلــك هــو علــى ســبيل احلكايــة أنــه قــد‬\n‫ذكــر يف تتمــة كالمــه أنــه اتصــل عليــه املدعــو ‪ ........‬وطلــب منــه أن‬\n‫يكــون األثــاث مببلــغ خمســة وســبعني ألــف ريــال وأنــه رفــض ذلــك وهــذا‬\n‫يــدل علــى عــدم إقــراره بــأن املبلــغ الباقــي هــو مقابــل األثــاث هــذا وقــد‬\n‫أضــاف املدعــي بقولــه إن كامــل األثــاث موجــود لــدي ومســتعد بتســليمه‬\n‫للمدعــى عليــه هكــذا قــال وحيــث األمــر مــا ذكــر لــم يظهــر لــي مــا‬\n‫يوجــب العــدول عمــا حكمــت بــه‪ .‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                         ‫محمــد وعلــى ألــه وســلم حــرر يف ‪1433/10/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء ‪1433/12/22‬هـ فتحت‬\n‫اجللســة الســاعة ‪ 09.00‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وبرفقهــا القــرار رقــم ‪ 33460003‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫واملتضمــن (أنــه بدراســة مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة وجــد‬\n‫لألكثريــة أنــه غيــر مقنــع إلقــرار املدعــي باســتالم املبلــغ احملكــوم بــه‬\n\n\n                                                                                       ‫‪102‬‬\n\f      ‫يف الصــك املشــار إليــه يف الفقــرة األولــى مــن قــرار الدائــرة وتقريــره يف‬\n      ‫نفــس الصــك بــأن االتفاقيــة األخيــرة لــم تشــر إلــى املبلــغ املســلم وهــذا‬\n      ‫يــدل علــى أنــه مــن الثمــن مــا دام لــم يشــترط عــدم اعتبــاره وقــت العقــد‬\n      ‫والكتابــة يف شــيك املائتــي ألــف ريــال رقــم ‪ 147‬يف ‪1427/3/9‬ه ـ‬\n      ‫املســحوب علــى شــركة الراجحــي املصرفيــة بأنهــا دفعــت مــن قيمــة‬\n      ‫فلــة املنــار فعلــى فضيلتــه إعــادة النظــر وتقريــر مــا يظهــر لــه وإجــراء مــا‬\n      ‫يلــزم نحــوه وإحلــاق ملخــص مــا يجريــه يف الضبــط إلــى الصــك وســجله‬\n      ‫ومــن ثــم إعــادة املعاملــة حســب التعليمــات ‪ .‬وبــاهلل التوفيــق ) ا‪.‬ه ـ وجوابـ ًا‬\n      ‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول أنــه ســبق وأن أثبــت فضيلــة‬\n      ‫ســلفنا بالصــك الصــادر منــه برقــم ‪ 17/43‬وتاريــخ ‪1430/11/23‬ه ـ بأن‬\n      ‫مبلــغ املائتــي ألــف غيــر داخــل يف االتفاقيــة األخيــرة بعــد أن أدى املدعــي‬\n      ‫اليمــن علــى نفــي ذلــك بعــد طلــب املدعــى عليــه لهــا وعليــه فلــم يظهــر‬\n      ‫لــي مــا يوجــب العــدول عمــا حكمــت بــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n                                                                     ‫‪1433/12/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬ففــي يــوم الســبت ‪1433/02/09‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 45‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض وبرفقهــا القــرار رقــم ‪ 3410470‬وتاريــخ ‪1434/01/12‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم‪ .‬إ‪.‬ه ـ ‪ ،‬وللبيــان جــرى حتريــره ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪1434/02/09‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أن ‪ ...........‬القاضــي باحملكمــة العامــة بالريــاض يــوم االثنــن املوافــق‬\n\n\n‫‪103‬‬\n\f‫‪1434/05/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 9.45‬وفيهــا حضــر املدعــي‬\n‫‪ ........‬وأقــر باســتالم كامــل املبلــغ وقــدره مائتــا ألــف ريــال مســحوب‬\n‫علــى مصــرف الراجحــي بشــيك رقــم ‪ 252055‬وتاريــخ ‪1434/4/29‬ه ـ‬\n‫وتعتبــر القضيــة منتهيــة‪ .‬وبــاهلل التوفيــق‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/5/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعــت الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة لهــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بالريــاض املســاعد باخلطاب رقــم ‪332180983‬‬\n‫وتاريــخ ‪1434/01/03‬ه ـ املرفــق بهــا الصــك رقــم ‪ 33192371‬وتاريــخ‬\n‫‪1433/04/14‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ............ /‬املتضمــن‬\n‫احلكــم يف الدعــوى املقامــة مــن ‪ ............./‬ضــد ‪ ........ /‬والــذي ســبق‬\n‫أن لوحــظ عليــه بالقــرار رقــم‪ 33460003‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫وبدراســة مــا أجــراه فضيلتــه بعــد املالحظــة قــررت الدائــرة املصادقــة‬\n‫علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪104‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":97,"source_page_end":104,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c45b1daaf4cfa541b4e63a398c125cfc19fdb4523f6fc36cd4ee3c6fb96686a1","normalized_text_hash":"77830c36bdf2fec13591290076f4db417ca37e3f864ae1e8439cc5a7d98e0415","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p97-33192371"},{"id":"4a3d019d-1635-5262-9879-65bc7a197c8b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع تراب -عدم قبض كامل الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول -اليمن للمدعي -احلكم غيابي ا بتسليم باقي الثمن للمدعي -الغائب على حجته متى حضر .","document_number":"3304195","case_number":"41056","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/18","year":"1434","subject":"بيع -بيع تراب -عدم قبض كامل الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول -اليمن للمدعي -احلكم غيابي ا بتسليم باقي الثمن للمدعي -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/6/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3304195 :‬‬\n                            ‫َر ْق ُم الدعوى‪41056 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3425305‬تاريخه‪1434/1/28 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع تــراب ‪ -‬عــدم قبــض كامــل الثمــن ‪ -‬عــدم حضــور املدعــى‬\n      ‫عليــه ‪ -‬شــهادة الشــهود العــدول ‪ -‬اليمــن للمدعــي‪ -‬احلكــم غيابي ـ ًا‬\n         ‫بتســليم باقــي الثمــن للمدعــي‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم (لــو يعطــى النــاس بدعواهــم الدعــى نــاس‬\n                   ‫دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن الشــركة املدعــى عليهــا والغائبــة عــن املجلــس‬\n      ‫الشــرعي اتفقــت معــه علــى شــراء تــراب مــن مزرعتــه مبقابــل معــن‪ ،‬وقد‬\n      ‫قامــت الشــركة بتحميــل التــراب مقابــل مبلــغ معــن قامــت بســداد جــزء‬\n      ‫منــه ولــم تقــم بســداد الباقــي ‪ ،‬أحضــر املدعــي شــاهدين شــهدا بقيــام‬\n      ‫الشــركة بتحميــل تــراب مــن مزرعــة املدعــي‪ ،‬كمــا أن املدعــي أدى‬\n      ‫اليمــن الشــرعية علــى صحــة دعــواه ‪ -‬صــدر احلكــم بإلــزام الشــركة‬\n      ‫املدعــى عليهــا بدفــع املبلــغ املدعــى بــه والغائــب علــى حجتــه متــى حضــر‬\n                                   ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪105‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالريــاض برقــم ‪ 41056‬وتاريــخ ‪ 1431/09/11‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 31159750‬وتاريــخ ‪ 1431/09/05‬ه ـ يف‬\n‫يــوم الســبت املوافــق ‪ 1432/6/11‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة والربــع وكان الوقــت احملــدد لهــا هــو الســاعة العاشــرة وفيهــا‬\n‫حضــر ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪............‬‬\n‫ولــم حتضــر املدعــى عليهــا شــركة ‪ ..............‬وقــد وردتنــا ورقــة طلــب‬\n‫احلضــور مــن قســم احملضريــن برقــم ‪ 32441909‬يف ‪1432/4/25‬ه ـ‬\n‫وقــد تضمنــت توقيــع املدعــو ‪ ...........‬محاســب الشــركة املدعــى عليهــا‬\n‫بتبلــغ الشــركة املدعــى عليهــا مبوعــد هــذه اجللســة ‪ ،‬وبنــاء عليــه فقــد‬\n‫مت رفــع اجللســة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر مــن ميثــل‬\n‫املدعــى عليهــا شــركة ‪...........‬هــذا وقــد أبــرز املدعــي خطــاب شــرطة‬\n‫امللــز رقــم بــدون وتاريــخ ‪1433/1/22‬ه ـ املتضمــن تعــذر ابــاغ املدعــى‬\n‫عليهــا حســب احملضــر املرفــق مت طلبهــم للحضــور اكثــر مــن مــرة‬\n‫ولــم يحضــر لدينــا مــن قبلهــم احــد حتــى تاريخــه هــذا وبتصفــح اوراق‬\n‫املعاملــة وجــدت بــن طياتهــا ورقــة التبليــغ مبوعــد اجللســة احملــددة يف‬\n‫تاريــخ ‪1432/2/4‬ه ـ املوقعــة مــن قبــل ‪.............‬املديــر املالــي للشــركة‬\n‫وبنــاء عليــه فقــد اذنــت للمدعــي يف تقــدمي دعــواه فادعــى قائــا‪ :‬ادعــي‬\n‫علــى الغائــب عــن املجلــس الشــرعي شــركة ‪ ............‬بأننــي ســبق وان‬\n‫اتفقــت مــع املدعــى عليهــا بتاريــخ ‪2009/4/15‬م علــى شــراء املدعــى‬\n\n                                                                                   ‫‪106‬‬\n\f      ‫عليهــا لتــراب مــن مزرعتــي الواقعــة يف حائــل يف املوقــع ‪ ....‬مــن مســار‬\n      ‫ســكة احلديــد علــى شــكل ردود قالبيــات وان يكــون ســعر الــرد‬\n      ‫عشــرة ريــاالت وقــد قامــت الشــركة بتحميــل ردود بلغــت قيمتهــا مائــة‬\n      ‫وواحــد وتســعون ألــف وســتمائة ريــال متثــل قيمــة تســعة عشــر ألــف ومائــة‬\n      ‫وســتني رد قــاب وقــد ســلمتني الشــركة املدعــى عليهــا مــن هــذا املبلــغ‬\n      ‫عشــرة آالف ريــال وتبقــى يف ذمتهــا مبلغـ ًا وقدرهــا مائــة وواحــد وثمانــون‬\n      ‫ألفـ ًا وســتمائة ريــال أطلــب يف دعــواي هــذه احلكــم علــى املدعــى عليهــا‬\n      ‫بســداد هــذا املبلــغ هــذه دعــواي وبســؤاله هــل لديــه بينــة قــال‪ :‬نعــم‬\n      ‫ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد مت رفــع اجللســة‬\n      ‫‪ ،‬ثــم يف جلســة أخــرى حضــر املدعــي ‪ ................‬ولــم يحضــر مــن ميثــل‬\n      ‫الشــركة املدعــى عليهــا وقــد ســبق أن تقــدم املدعــي بطلــب اســتخالف‬\n      ‫محكمــة األجفــر بحائــل لســماع بينتــه وقــد جــرى منــي الكتابــة إلــى‬\n      ‫احملكمــة املذكــورة الســتخالف قاضــي احملكمــة يف ســماع شــهود‬\n      ‫املدعــي باخلطــاب رقــم ‪ 33/519547‬يف ‪1433/3/19‬ه ـ هــذا وقــد وردنا‬\n      ‫خطــاب مديــر شــرطة امللــز رقــم بــدون وتاريــخ ‪1433/3/9‬ه ـ املتضمــن‬\n      ‫أن صاحــب الشــركة غيــر متواجــد وقــد تبلــغ موظــف الشــركة بهــذا‬\n      ‫املوعــد وباالطــاع علــى طلــب احلضــور وجــد أنــه موقــع مــن قبــل ‪.........‬‬\n      ‫وقــال املدعــي إننــا حضرنــا لــدى قاضــي محكمــة األجفر وســمع شــهادة‬\n      ‫ـاء عليــه فقــد قــررت رفــع اجللســة إلــى حــن ورود اجلــواب ‪،‬‬   ‫شــهودي وبنـ ً‬\n      ‫ويف جلســة أخــرى حضــر ‪ ..............‬املدونــة هويتــه ســابقا ولــم يحضــر‬\n      ‫مــن ميثــل املدعــى عليهــا شــركة ‪ ....‬هــذا وقــد وردنــا خطــاب قاضــي‬\n      ‫احملكمــة العامــة باألجفــر رقــم ‪ 427‬يف ‪1433/4/7‬ه ـ املرفــق بــه صــورة‬\n      ‫الضبــط عــدد ‪ 5‬يف ‪1433/4/7‬ه ـ املتضمــن نــص احلاجــة منــه فقــد‬\n\n\n‫‪107‬‬\n\f‫حضــر ‪............‬املذكــور أعــاه وجــرى ســؤاله عــن بينتــه فقــال أحضــرت‬\n‫شــاهدين أطلــب ســماع شــهادتهما وأحضــر للشــهادة وأدائهــا ‪...........‬‬\n‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ..........‬واملولــود يف ‪1395/7/1‬ه ـ‬\n‫وبســؤاله عــن مهنتــه وجهــة اتصالــه باخلصــوم قــال ال أعمــل وال يوجــد‬\n‫بينــي وبــن املتداعيــن أي قرابــة إال أن املدعــي جــار لنــا يف املزرعــة يف‬\n‫قريــة ‪ ....‬التابعــة ملركــز ‪ ....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n‫هلل بــأن هنــاك قالبيــات وشــيوالت تابعــة للــ‪ ..........‬وهي شــركة ‪.............‬‬\n‫كانــت حتمــل مــن مزرعــة ‪ ................‬تــراب حتفــر الشــيوالت يف املزرعــة‬\n‫ثــم حتملهــا القالبيــات وهــي تضعهــا يف ســكة القطــار وكان بدايتهــم‬\n                                   ‫يف أوائــل عــام ‪1430‬ه ـ تقريبــا شــهر صفــر‬\n‫احلمــد هلل وحــده وبعــد ف ففــي يــوم الســبت املوافــق ‪ 1432/6/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــر والربــع وكان الوقــت احملــدد لهــا‬\n‫هــو الســاعة العاشــرة وفيهــا حضــر ‪ ...............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .................‬ولــم حتضــر املدعــى عليهــا شــركة‬\n‫‪ .............‬وقــد وردتنــا ورقــة طلــب احلضــور مــن قســم احملضريــن برقــم‬\n‫‪ 32441909‬يف ‪1432/4/25‬ه ـ وقــد تضمنــت توقيــع املدعــو ‪.............‬‬\n‫محاســب الشــركة املدعــى عليهــا بتبلــغ الشــركة املدعــى عليهــا مبوعد‬\n‫هــذه اجللســة ‪ ،‬وبنــاء عليــه فقــد مت رفــع اجللســة وحتــدد النظــر فيهــا يــوم‬\n‫األربعــاء املوافــق ‪1432/10/16‬ه ـ الســاعة العاشــرة والنصــف وقــررت‬\n‫الكتابــة إلــى قســم احملضريــن باحملكمــة إلبــاغ املدعى عليهــا باملوعد‬\n‫اآلخــر وبــه ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر والنصــف وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                               ‫يف ‪1432/6/11‬ه ـ‬\n\n\n                                                                                       ‫‪108‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1432/10/16‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 05‬وفيهــا حضــر املدعــي ولــم حتضــر‬\n      ‫املدعــى عليهــا وال مــن ينــوب عنهــا ولــم يــرد مــا يفيــد تبلــغ مــن ميثلهــا‬\n      ‫ومبــا أن املدعــى عليــه لــم يتبلــغ لشــخصه لــذا فقــد قــررت رفــع اجللســة‬\n      ‫وحتديــد موعــد آخــر وإبــاغ املدعــى عليــه بــه وحتــدد النظــر فيهــا يــوم‬\n      ‫الســبت بتاريــخ ‪1433/1/22‬ه ـ الســاعة التاســعة والنصــف وبــه ختمــت‬\n      ‫اجللســة يف متــام الســاعة ‪ 11:14‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1432/10/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم الســبت املوافــق ‪1433/1/22‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 10 : 07‬وكان الوقت احملدد لها هو الســاعة ‪09.30‬‬\n      ‫وفيهــا حضــر املدعــي ولــم يحضــر مــن ميثــل املدعــى عليهــا شــركة‬\n      ‫‪ ...........‬هــذا وقــد ابــرز املدعــي خطــاب شــرطة امللــز رقــم بــدون وتاريــخ‬\n      ‫‪1433/1/22‬ه ـ املتضمــن تعــذر إبــاغ املدعــى عليهــا حســب احملضــر‬\n      ‫املرفــق مت طلبهــم للحضــور اكثــر مــن مــرة ولــم يحضــر لدينــا مــن قبلهــم‬\n      ‫احــد حتــى تاريخــه هــذا وبتصفــح أوراق املعاملــة وجدت بــن طياتها ورقة‬\n      ‫التبليــغ مبوعــد اجللســة احملــددة يف تاريــخ ‪1432/2/4‬ه ـ املوقعــة من قبل‬\n      ‫‪ ..........‬املديــر املالــي للشــركة وبنــاء عليــه فقــد أذنــت للمدعــي يف تقــدمي‬\n      ‫دعــواه فادعــى قائــا‪ :‬ادعــي علــى الغائــب عــن املجلــس الشــرعي شــركة‬\n      ‫‪ ..........‬بأننــي ســبق وان اتفقــت مــع املدعــى عليهــا بتاريــخ ‪2009/4/15‬م‬\n      ‫علــى شــراء املدعــى عليهــا لتــراب مــن مزرعتــي الواقعــة يف حائــل يف‬\n      ‫املوقــع ‪ ....‬مــن مســار ســكة احلديــد علــى شــكل ردود قالبيــات وان‬\n      ‫يكــون ســعر الــرد عشــرة ريــاالت وقــد قامــت الشــركة بتحميــل ردود‬\n      ‫بلغــت قيمتهــا مائــة وواحــد وتســعون ألــف وســتمائة ريــال متثــل قيمــة‬\n\n\n‫‪109‬‬\n\f‫تســعة عشــر ألــف ومائــة وســتني رد قــاب وقــد ســلمتني الشــركة‬\n‫املدعــى عليهــا مــن هــذا املبلــغ عشــرة آالف ريــال وتبقــى يف ذمتهــا مبلغـ ًا‬\n‫وقدرهــا مائــة وواحــد وثمانــون ألفـ ًا وســتمائة ريــال أطلــب يف دعواي هذه‬\n‫احلكــم علــى املدعــى عليهمــا بســداد هــذا املبلــغ هــذه دعــواي وبســؤاله‬\n‫هــل لديــه بينــة قــال‪ :‬نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء‬\n‫عليــه فقــد مت رفــع اجللســة وقــررت إبــاغ املدعــى عليهــا باملوعــد القــادم‬\n‫وحتــدد النظــر فيهــا يــوم األحــد بتاريــخ ‪1433/4/11‬هـ الســاعة العاشــرة‬\n‫والنصــف وبــه ختمــت اجللســة يف متــام الســاعة ‪ 10:30‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪1432/1/22‬هـ‬\n‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق‪ 1433/04/11‬ه ـ افتتحــت‬\n‫اجللسة الساعة ‪ 11 : 11‬وفيها حضر املدعي ‪ ............‬ولم يحضر من ميثل‬\n‫الشــركة املدعــى عليهــا وقــد ســبق أن تقــدم املدعــي بطلــب اســتخالف‬\n‫محكمــة األجفــر بحائــل لســماع بينتــه وقــد جــرى منــي الكتابــة إلــى‬\n‫احملكمــة املذكــورة الســتخالف قاضــي احملكمــة يف ســماع شــهود‬\n‫املدعــي باخلطــاب رقــم ‪ 33/519547‬يف ‪1433/3/19‬ه ـ هــذا وقــد وردنا‬\n‫خطــاب مديــر شــرطة امللــز رقــم بــدون وتاريــخ ‪1433/3/9‬ه ـ املتضمــن‬\n‫أن صاحــب الشــركة غيــر متواجــد وقــد تبلــغ موظــف الشــركة بهــذا‬\n‫املوعــد وباالطــاع علــى طلــب احلضــور وجــد أنــه موقــع مــن قبــل ‪...........‬‬\n‫وقــال املدعــي إننــا حضرنــا لــدى قاضــي محكمــة األجفر وســمع شــهادة‬\n‫شــهودي وبنــاءا عليــه فقــد قــررت رفــع اجللســة إلــى حــن ورود اجلــواب‬\n‫وحتــدد النظــر فيهــا يــوم األثنــن املوافــق ‪1433/6/16‬هـ الســاعة ‪11.30‬‬\n‫وبــه ختمــت اجللســة الســاعة ‪ 11.25‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n\n\n                                                                                      ‫‪110‬‬\n\f           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/11‬ه ـ‬\n      ‫واســتمروا عشــرين يومــا علــى هــذا املنــوال ثــم توقفــوا تقريبــا اســبوعني‬\n      ‫إلــى ثالثــة ثــم رجعــوا للحفــر مــن مزرعتــه وحتميــل التــراب لفتــرة ال تقــل‬\n      ‫عن خمســة أشــهر علما أن ســكني شــرق مزرعة املذكور وهي ال تبعد‬\n      ‫عنــي أكثــر مــن نصــف كيلــو تقريبــا ونحــن نســمع إزعــاج الشــيوالت‬\n      ‫والقالبيــات ونراهــا أثنــاء دخولنــا ألن طريــق الشــيوالت والقالبيــات‬\n      ‫ال بــد أن ميــر علــى البيــت هــذا مــا أشــهد بــه كمــا أحضــر للشــهادة‬\n      ‫وأدائهــا ‪ .........‬ســعودي بالســجل املدنــي رقــم ‪ .................‬واملولــود بتاريــخ‬\n      ‫‪1398/7/1‬ه ـ وبســؤاله عــن مهنتــه وجهــة اتصالــه باخلصــوم قــال أنــا ال‬\n      ‫أعمــل رســمي إال أننــي مــؤذن جامــع ‪ ...‬وال يوجــد بينــي وبــن أي اخلصــوم‬\n      ‫أي قرابــة وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل بــأن شــخص‬\n      ‫‪ ...........‬نســيت اســمه قد اتفق مع ‪ .............‬على حتميل تراب من مزرعة‬\n      ‫‪ ..............‬وكتبــوا العقــد لدينــا يف البيــت وبعدهــا رأيناهــم يحفــرون مــن‬\n      ‫مزرعــة ‪ ........‬ويحملــون يف القالبيــات وميــرون يف طريقهــم علــى بيتنــا‬\n      ‫وأزعجونــا ليــا ونهــارا حتــى طلبنــا منهــم أن يتحولــوا إلــى طريــق آخــر‬\n      ‫وأنــا مــؤذن اجلامــع ومكثــي دائمــا يف قريــة ‪ ...‬وأراهــم علمــا أن املســافة‬\n      ‫بــن بيتنــا ومزرعــة ‪ .......‬ال تصــل إلــى كيلــو متــر بــل أقــل وحملــوا أوال‬\n      ‫عشــرين يومــا ثــم توقفــوا ثــم اكملــوا احلفــر ألكثــر مــن خمســة أشــهر‬\n      ‫وأمــا عــن وقــت حفرهــم فــا أذكــر بالضبــط قبــل ســنة ونصــف أو أقــل‬\n      ‫أو أكثــر هــذا مــا أشــهد بــه كمــا حضــر كل مــن ‪ ............‬ســعودي‬\n      ‫اجلنســية بالســجل املدنــي رقــم ‪..............‬و‪ ...........‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم ‪ ...............‬اللذيــن شــهدا بــأن الشــاهدين مــن أهــل‬\n      ‫الصــاح والصــاة ولــم يعرفــا عنهمــا الكــذب هــذا مــا قــاال وعليــه فقــد‬\n\n\n‫‪111‬‬\n\f‫جــرى إثباتــه أه ـ وبســؤال املدعــي هــل لديــه زيــادة بينــة أبــرز صــورة عقــد‬\n‫شــراء علــى مطبوعــات شــركة ‪ ..........‬الطــرف األول شــركة ‪............‬‬\n‫وميثلهــا ‪ .........‬الطــرف الثانــي ‪ ..............‬وتضمــن العقــد شــراء تــراب مــن‬\n‫املزرعــة التابــع للثانــي علــى شــكل ردود وتضمــن يف الفقــرة الثالثــة‬\n‫ســعر الــرد الواحــدة ثالثــة ريــال ويكــون ســعر الــرد عشــرة ريــاالت‬\n‫اعتبــارا مــن ‪2009/5/9‬م كمــا وجــدت بــن طيــات املعاملــة خطــاب مــن‬\n‫‪ ..............‬موجــه لشــرطة امللــز يفيــد أن حســاب املدعــي لــدى شــركة‬\n‫‪ ............‬وليــس لديــه شــخصيا فجــرى ســؤال املدعــي هــل لديــه زيــادة‬\n‫بينــة قــال ال ليــس لــدي إال مــا قدمــت وأســتعد بــأداء اليمــن فقــال يف‬\n‫هــذا املجلــس واهلل العظيــم إننــي اتفقــت مــع املدعــى عليهــا شــركة‬\n‫‪...........‬علــى حتميــل تــراب مــن مزرعتــي بســعر الــرد عشــر ريــاالت وأنــه‬\n‫اســتحق يف ذمتهــم مبلغــا قــدره مائــة وواحــد وثمانــون ألفــا وســتمائة ريــال‬\n‫وبنــاء علــى مــا ســبق مــن الدعــوى واالجابــة ولقولــه صلــى اهلل عليــه وســلم‬\n‫لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن‬\n‫اليمــن علــى املدعــى عليــه ومبــا أن املدعــي قــدم شــاهديه املعدلــن‬\n‫شــرعا واللذيــن شــهدا بقيــام املدعــى عليهــا بتحميــل تــراب مــن مزرعــة‬\n‫املدعــي ومبــا ان املدعــي أدى اليمــن الشــرعية علــى صحــة دعــواه ومبــا‬\n‫أن الشــركة املدعــى عليــه قــد تبلــغ مديرهــا بهــذه الدعــوى لذلــك كلــه‬\n‫فقــد حكمــت علــى املدعــى عليــه شــركة ‪ ..............‬غيابيــا بــأن تســلم‬\n‫للمدعــي املبلــغ املدعــى بــه والــذي قــدره مائــة وواحــد وثمانــون ألفــا‬\n‫وســتمائة ريــال واملدعــى عليــه علــى حجتــه متــى مــا حضــر وبعرضــه علــى‬\n‫املدعــي قنــع بــه وقــررت بعــث صــورة مــن نســخة احلكــم للمدعــى عليهــا‬\n‫وإفهامهــم بــأن لهــم مهلــة ثالثــن يــوم مــن تاريــخ االســتالم لتقــدمي الئحتهم‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫االعتراضيــة فــإذا انتهــت املهلــة ولــم يتقدمــوا بالئحتهــم االعتراضيــة‬\n      ‫ســقط حقهــم باالعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة‬\n      ‫الســاعة ‪ 1.15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/02/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 9:15‬وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 34164381‬يف ‪1434/2/10‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n      ‫رقــم ‪ 3425305‬يف ‪1434/1/28‬ه ـ واملتضمــن وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم‬\n      ‫واهلل املوفــق أه ـ ‪ ،‬وعليــه جــرى تهميــش مبوجبــه ‪ ،‬وبــه ختمــت اجللســة‬\n      ‫يف متــام الســاعة ‪ 09:20‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/27‬ه ـ ‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":105,"source_page_end":113,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"999729b8476aa152572a0690762dae6218fb18b76fc3a1d94e8999c1e37dabee","normalized_text_hash":"99409da72ffb37901d4043a2af056df6fed935660a10cd43fe8603cf3cbf3a03","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p105-3304195"},{"id":"0b400ab5-f73b-5a37-807f-0f2bd12012ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -شراء املدعى عليه سيارة -كفالة غرم وأداء للمدعى عليه -سداد املدعى عليه جزء من ثمن السيارة -مطالبة البائع املدعي (الكفيل) بسداد باقي الثمن -سداد املدعي كامل الثمن مبوجب صك -للكفيل حق الرجوع على مكفوله فيما غرمه عنه -احلكم غيابي ا بإلزام املدعى عليه بدفع املبلغ املدعى به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"3410373","case_number":"47263","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة احلقوقية اخلامسة رقم 34169008وتاريخ 1434/2/23ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"بيع -شراء املدعى عليه سيارة -كفالة غرم وأداء للمدعى عليه -سداد املدعى عليه جزء من ثمن السيارة -مطالبة البائع املدعي (الكفيل) بسداد باقي الثمن -سداد املدعي كامل الثمن مبوجب صك -للكفيل حق الرجوع على مكفوله فيما غرمه عنه -احلكم غيابي ا بإلزام املدعى عليه بدفع املبلغ املدعى به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410373 :‬‬\n                      ‫َر ْق ُم الدعوى‪47263 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34169008‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬شــراء املدعــى عليــه ســيارة ‪ -‬كفالــة غــرم وأداء للمدعــى عليــه‬\n‫‪ -‬ســداد املدعــى عليــه جــزء مــن ثمــن الســيارة ‪ -‬مطالبــة البائــع املدعــي‬\n‫(الكفيــل) بســداد باقــي الثمــن ‪ -‬ســداد املدعــي كامــل الثمــن مبوجــب‬\n‫صــك ‪ -‬للكفيــل حــق الرجــوع علــى مكفولــه فيمــا غرمــه عنــه ‪ -‬احلكــم‬\n‫غيابي ـ ًا بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ -‬الغائــب علــى‬\n‫حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                                                      ‫املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n‫‪( -‬ويرجــع الضامــن وكل مــن أدى عــن غيــره دينــا واجبــا بنيــة الرجــوع)‬\n                                                ‫يف كشــاف القناع (‪. )372/3‬‬\n                            ‫‪ -‬املادة (‪176 ، 55‬من نظام املرافعات الشرعية) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلــه ســبق أن كفــل املدعــى عليه كفالة‬\n‫غــرم وأداء يف ثمــن ســيارة ‪ ،‬ســدد املدعــى عليــه جــزء مــن ثمنهــا وامتنــع‬\n‫ـاء علــى صــك‬ ‫عــن ســداد الباقــي ‪ ،‬قــام املدعــي بســداد باقــي الثمــن بنـ ً‬\n‫يلزمــه بالســداد ‪ ،‬مت تبليــغ املدعــى عليــه بالدعــوى إال أنــه لــم يحضــر‪،‬‬\n‫وملــا كانــت القاعــدة أن للكفيــل حــق الرجــوع علــى مكفولــه فيمــا‬\n\n                                                                                     ‫‪114‬‬\n\f      ‫غرمــه عنــه حكمــت احملكمــة غيابيـ ًا بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n      ‫املدعــى بــه للمدعــي أصالــة ‪ -‬مت رفــع احلكــم حملكمــة االســتئناف‬\n      ‫لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n      ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض برقــم ‪ 47263‬وتاريــخ ‪ 1431/11/09‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 31185780‬وتاريــخ ‪ 1431/11/09‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1432/02/07‬ه ـ حضــر املدعــي وكالــة ‪.............‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ ............‬بصفتــه وكيــا عــن ‪...........‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...........‬مبوجــب صــك وكالــة صــادر‬\n      ‫مــن كتابــة العــدل الثانيــة يف جيــزان برقــم ‪ 8975‬يف ‪1431/11/1‬ه ـ‬\n      ‫ولــم يحضــر املدعــى عليــه ‪.................‬وعــاد إلينــا خطــاب التبليــغ رقــم‬\n      ‫‪ 32/123012‬يف ‪1431/11/9‬ه ـ وقــد دون عليــه محضــر اخلصوم رفض‬\n      ‫املوظــف املختــص اســتالم البــاغ لكــون املدعــى عليه يتواجــد يف الدوام‬\n      ‫املســائي‪ .‬ويف يــوم الســبت املوافــق ‪1432/5/12‬ه ـ حضر املدعي وكالة‬\n      ‫‪ ...............‬املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه‬\n      ‫‪ ............‬وعــاد إلينــا خطــاب التبليــغ املــؤرخ يف ‪1432/2/7‬ه ـ وقــد دون‬\n      ‫عليــه محضــر اخلصــوم رفــض املوظــف املختــص اســتالم البــاغ والتوقيــع‬\n      ‫وذلــك بعــد االتصــال علــى املدعــى عليــه فقــال املوظــف ال تســتلم البــاغ ‪.‬‬\n      ‫ويف يــوم األربعــاء املوافق‪1433/03/30‬ه ـ حضــر املدعــي وكالــة ‪..........‬‬\n      ‫املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه ‪ .........‬ووردنــا‬\n‫‪115‬‬\n\f‫جــواب مديــر مركــز شــرطة امللــز رقــم ‪ 1451‬وتاريــخ ‪1433/2/6‬ه ـ‬\n‫املتضمــن االتصــال باملدعــى عليــه بواســطة اجلــوال وأفــاد أنــه يف جيــزان‬\n‫وبنــاء علــى تبلــغ املدعــى عليــه مرتــن وعــدم جتاوبــه باســتالم التبليــغ‬\n‫وبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات جــرى ســماع الدعــوى غيابيــا‬\n‫وبســؤال املدعــي عــن دعــواه أجــاب قائــا‪ :‬ســبق أن كفــل موكلــي‬\n‫املدعــى عليــه كفالــة غــرم وأداء يف ثمــن ســيارة هايلوكــس غمارتــن‬\n‫موديــل ‪2000‬م اشــتراها املدعــى عليــه مــن ‪ ...............‬يف عــام ‪1421‬ه ـ‬\n‫بثمــن قــدره تســعون ألــف ريــال مقســطة كل شــهر ألــف وخمســمائة‬\n‫ريــال اعتبــارا مــن ‪1421/5/30‬ه ـ وســدد املدعــى عليــه مــن ثمنهــا تســعة‬\n‫آالف وســتمائة ريــال فقــط وبقــي مــن ثمنهــا ســبعون ألــف وأربعمائــة‬\n‫ريــال حــل منهــا أربعــة وخمســون ألــف ريــال ولــم يســددها للبائــع فأقــام‬\n‫البائــع دعــواه ضــد موكلــي لســداد باقــي الثمــن وصــدر مــن محكمــة‬\n‫محافــظ أبــو عريــش الصــك رقــم ‪ 3/6‬وتاريــخ ‪1425/1/9‬ه ـ بإلــزام‬\n‫موكلــي بســداد ذلــك املبلــغ للبائــع املذكــور وســدد موكلــي ذلــك املبلــغ‬\n‫أربعــة وخمســن ألــف وأربعمائــة ريــال ثــم املدعــى عليــه لــم يســدد للبائــع‬\n‫باقــي املبلــغ بعــد ذلــك احلكــم وقــدره ســتة عشــر ألــف ريــال فســددها‬\n‫موكلــي للبائــع بعــد ان طالبــه بهــا لــذا أطلــب إلــزام املدعــى عليــه أن‬\n‫يســدد ملوكلــي املبلــغ الــذي ســدده عنــه ســبعني ألــف وأربعمائــة ريــال‬\n‫هــذه دعــواي وبســؤاله عــن بينــة أبــرز صــورة الصــك املشــار إليــه أعــاه‬\n‫املتضمــن مــا ذكــره مــن الدعــوى ضــد موكلــه واحلكــم عليــه مببلــغ‬\n‫أربعمائــة وخمســن ألــف وأربعمائــة ريــال ثــم همــش عليــه بتســلم املدعــى‬\n‫عليــه ذلــك املبلــغ املدعــى بــه للبائــع وبســؤال املدعــي وكالــة عــن أصــل‬\n‫الصــك اســتعد بإحضــاره كمــا أبرز صورة ورقــة على مطبوعات ‪...........‬‬\n\n\n                                                                                     ‫‪116‬‬\n\f      ‫لبيــع وشــراء الســيارات املــؤرخ يف ‪1431/7/14‬ه ـ ونصــه بعــد املقدمــة ما‬\n      ‫يلــي‪ :‬تشــهد مؤسســة ‪ ..............‬بــأن املدعــو ‪ ..........................‬قــد حكــم‬\n      ‫بالصــك رقــم ‪ 3/6‬يف ‪1425/1/9‬ه ـ مببلــغ وقــدره أربعــة وخمســون ألــف‬\n      ‫وأربعمائــة ريــال وقــام بدفــع املبلــغ املــدون يف ‪ 54400‬وقــام بدفــع باقــي‬\n      ‫املبلــغ وبذلــك يكــون املبلــغ املدفــوع مــن قبــل املدعــو ‪........................‬‬\n      ‫‪ 70400‬ســبعون ألــف وأربعمائــة وقــد أعطــي هــذا املشــهد ختــم املؤسســة‬\n      ‫مــع توقيــع‪ .‬أه ـ وأمــرت بالكتابــة إلــى محكمــة أبوعريــش لتزويدنــا‬\n      ‫بصــورة طبــق األصــل مــن صــك احلكــم املشــار إليــه أعــاه واســتخالف‬\n      ‫احملكمــة إلحضــار ‪.............‬وســؤاله عمــا يدعيــه املدعــي مــن ســداده‬\n                                                       ‫للمبلــغ حســب مــا جــاء يف املشــهد‪.‬‬\n      ‫ويف يــوم االثنــن املوافق‪1434/01/12‬ه ـ حضــر املدعي وكالــة ‪............‬‬\n      ‫املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه ‪...............‬‬\n      ‫ووردنــا جــواب القائــم بعمــل رئيــس احملكمــة العامــة مبحافظــة أبــو‬\n      ‫عريــش املكلــف برقــم ‪ 3/1383/3405‬وتاريــخ ‪1433/8/26‬ه ـ‬\n      ‫وبرفقــه صــورة طبــق األصــل مــن مكتــب القضائــي رقــم ‪ 3‬وهــذا نصــه‬\n      ‫بعــد املقدمــة حضــر املدعــي وكالــة ‪ ..............‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم (‪ )............‬مبوجــب الوكالــة رقــم ‪ 29‬وتاريخ ‪1432/2/15‬هـ‬\n      ‫الصــادرة مــن كتابــة عــدل أبــو عريــش والتــي تخولــه حــق اإلقــرار وأقــر‬\n      ‫بقولــه‪ :‬إن موكلــي اســتلم كامــل املبلــغ املطالــب فيــه يف القضيــة‬\n      ‫الصــادر بهــا الصــك رقــم ‪ 3/6‬وتاريــخ ‪1425/1/9‬ه ـ الصــادر مــن‬\n      ‫محكمــة أبــو عريــش كمــا أن موكلــي ال يطالــب املدعــى عليــه بــأي‬\n      ‫مبلــغ بهــذه البيعــة مطلقــا علمــا بــأن املبلــغ ســبعون ألــف ريــال هكــذا‬\n      ‫قــرر‪ .‬أه ـ ومبــا أن املدعــي وكالــة ذكــر يف دعــواه أن موكلــه ســدد‬\n\n\n‫‪117‬‬\n\f‫ســبعني ألفـ ًا وأربعمائــة ريــال بينمــا جــاء يف الضبــط أعــاه حتديــد املبلــغ‬\n‫بســبعني ألــف ريــال أجــاب قائــا‪ :‬اقصــر دعــواي علــى املطالبــة مببلــغ‬\n‫ســبعني ألــف ريــال هكــذا قــرر ولــم يتــم مــن قبــل محكمــة أبــو عريــش‬\n‫إرفــاق صــورة طبــق األصــل مــن صــك احلكــم ‪ 3/6‬فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى وعــدم حضــور املدعــى عليــه ومــا أبــرزه املدعــي وكالــة‬\n‫مــن الصــك رقــم ‪ 3/6‬واســتخالفنا محكمــة أبــو عريــش وورود جوابهــم‬\n‫وبرفقــه صــورة ضبــط تضمنــت إقــرار احملكــوم لــه وكالــة باســتالم‬\n‫املبلــغ احملكــوم بــه ومبــا أن للكفيــل حــق الرجــوع علــى مكفولــه فيمــا‬\n‫غرمــه عنــه كمــا قــرره الفقهــاء قــال يف كشــاف القنــاع (‪:)372/3‬‬\n‫ويرجــع الضامــن وكل مــن أدى عــن غيــره دينــا واجبــا بنيــة الرجوع‪.‬أه ـ‬\n‫وقصــر املدعــي وكالــة دعــواه علــى مبلــغ ســبعني ألــف ريــال لــذا فقــد‬\n‫ألزمــت املدعــى عليــه الغائــب أن يدفــع للمدعــي أصالــة املبلــغ املدعــى‬\n‫بــه وقــدره ســبعون ألــف ريــال والغائــب علــى حجتــه متــى حضــر وبــه‬\n‫حكمــت وأمــرت إخــراج صــك مبوجبــه وإبــاغ احملكــوم عليــه بصورتــه‬\n‫لتقريــر قناعتــه أو معارضتــه وتقــدمي الئحــة اعتراضــه خــال ثالثــن‬\n‫يومــا فــإن مضــت مــدة االعتــراض ولــم يقــدم الئحــة اعتراضــه بعــد تبلغــه‬\n‫ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪1434/01/12‬هــ‪ .‬ويف يــوم االثنــن املوافق‪1434/02/25‬ه ـ افتتحــت‬\n‫اجللســة الســاعة بنــاء علــى شــرح رئيــس احملكمــة العامــة بالريــاض‬\n‫املســاعد علــى القيــد رقــم ‪ 34380999‬وتاريــخ ‪1434/02/16‬ه ـ وبرفقــه‬\n‫خطــاب مديــر مركــز شــرطة الفيصليــة واخلالديــة رقــم ‪12/6/961/2‬‬\n‫وتاريــخ ‪1434/02/12‬ه ـ بشــأن تســليم صــك احلكــم للمحكــوم عليــه‬\n\n\n                                                                                      ‫‪118‬‬\n\f      ‫‪ .............‬واملتضمــن إعــادة األوراق لعــدم معرفــة املدعــي وكالــة عنــوان‬\n      ‫املدعــى عليــه‪ .‬وبنــاء علــى تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى‬\n      ‫احملكــوم عليــه وبنــاء علــى املــادة ‪ 5/176‬مــن نظــام املرافعــات الشــرعية‬\n      ‫والئحتــه التنفيذيــة أمــرت بإحلاقــه علــى صكــه وســجله ورفــع احلكــم‬\n      ‫بدون الئحة اعتراض مع كامل ملف الدعوى إلى محكمة االستئناف‬\n      ‫بالريــاض لتدقيقــه‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/04/03‬ه ـ افتتحــت‬\n      ‫اجللســة بنــاء علــى ورود خطــاب رئيــس محكمــة االســتئناف بالريــاض‬\n      ‫املكلــف رقــم ‪ 34638402‬وتاريــخ ‪1434/3/28‬ه ـ وبرفقــه قــرار‬\n      ‫الدائــرة احلقوقيــة اخلامســة رقــم ‪ 34169008‬وتاريــخ ‪1434/2/23‬ه ـ‬\n      ‫املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم مــع تنبيــه‬\n      ‫فضيلتــه لتصحيــح مــا حتتــه خــط مــن مبلــغ‪ .‬وبــاهلل التوفيــق وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 31185780‬وتاريخ ‪1434/3/4‬هـ املرفق بها الصك الصادر من فضيلة‬\n      ‫القاضــي باحملكمــة الشــيخ‪ ................./‬املســجل برقــم ‪3410373‬‬\n      ‫وتاريــخ ‪1434/1/12‬ه ـ اخلــاص بدعوى‪............./‬وكالــة ضــد‪............/‬‬\n      ‫يف مبلــغ مــن املــال علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم‬\n      ‫فضيلتــه كمــا هــو موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم مــع تنبيــه‬\n      ‫فضيلتــه لتصحيــح مــا حتتــه خــط مــن مبلــغ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                            ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":114,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b61ce1a3295472344f6c1a52e382c96504dc5f877c35fb0888376582d6d0198","normalized_text_hash":"dcd6368af04ad7db1047063f6d5a380ed218c16b6066c6e2d75c50fc4bc92a45","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p114-3410373"},{"id":"e4fdb79c-7851-5261-af26-bb7ddad2f5e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة بأقساط -شرط حلول كامل الثمن حال تأخر املدين عن دفع ثالثة أقساط -بينة املدعي -حلف اليمن -عدم حضور املدعى عليه -احلكم غيابي ا بدفع كامل األقساط - الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","document_number":"33251132","case_number":"339922","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/17","year":"1434","subject":"بيع -بيع سيارة بأقساط -شرط حلول كامل الثمن حال تأخر املدين عن دفع ثالثة أقساط -بينة املدعي -حلف اليمن -عدم حضور املدعى عليه -احلكم غيابي ا بدفع كامل األقساط - الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33251132 :‬‬\n                     ‫َر ْق ُم الدعوى‪339922 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34262550‬تاريخه‪1434/7/9 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة بأقســاط ‪ -‬شــرط حلــول كامــل الثمــن حــال تأخــر‬\n‫املديــن عــن دفــع ثالثــة أقســاط‪ -‬بينــة املدعــي ‪ -‬حلــف اليمــن‪ -‬عــدم‬\n‫حضــور املدعــى عليــه ‪ -‬احلكــم غيابي ـ ًا بدفــع كامــل األقســاط ‪-‬‬\n‫الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة االســتئناف‬\n                                         ‫لتعــذر تبليــغ املدعــى عليــه ‪.‬‬\n\n\n\n\n‫‪ -1‬قــرار املجمــع الفقهــي ( صحــة شــرط مــن تأخــر عــن قســط مــن‬\n                                      ‫األقســاط فيحــل املبلــغ كامــا )‬\n‫‪ -2‬مــا ذكــره املجــد أبــو البــركات رحمــه اهلل يف محــرره بقولــه ( ومــن‬\n‫أدعــى علــى غائــب أو مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه‬\n       ‫بينــة ســمعت وحكــم لــه ويســتحلفه احلاكــم علــى بقــاء حقــه )‪.‬‬\n                             ‫‪ -3‬املادة ( ‪ ) 55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫بــاع املدعــي ســيارة للمدعــى عليــه مبوجــب عقــد‪ ،‬مت النــص يف العقــد‬\n‫علــى دفــع كامــل الثمــن حــال تأخــر املدعــى عليــه عــن دفــع ثالثــة‬\n‫أقســاط‪ ،‬قــدم املدعــي لصحــة دعــواه إقــرار املدعــى عليــه كتابــة مبــا‬\n\n                                                                                ‫‪124‬‬\n\f      ‫ســبق‪ ،‬حلــف املدعــي اليمــن علــى صحــة دعــواه‪ ،‬لــم يحضــر املدعــى‬\n      ‫عليــه‪ ،‬صــدر احلكــم غيابي ـ ًا بدفــع كامــل األقســاط املتبقيــة ‪ -‬رفــع‬\n      ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪-‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n      ‫فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة بتبــوك وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك‪/‬‬\n      ‫املســاعد برقــم ‪ 339922‬وتاريخ‪1433/1/3‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 3324540‬وتاريخ‪1433/1/3‬ه ـ حضــر ‪ ...........‬ســعودي اجلنســية‬\n      ‫ا عــن ‪................‬‬\n                            ‫مبوجــب الســجل املدنــي رقــم‪ ...........‬بصفتــه وكي ـ ً‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل بخميــس مشــيط برقــم‬\n      ‫‪ 770711000289‬وتاريــخ ‪1433/1/8‬ه ـ واملخــول لــه فيهــا حــق املرافعــة‬\n      ‫واملخاصمــة واملدافعــة وحضــور اجللســات ‪ ،‬ولــم يحضــر املدعــى عليــه‬\n      ‫رغــم تبلغــه باملوعــد لشــخصه مبوجــب اإلفــادة الصــادرة مــن مجموعــة‬\n      ‫الشــرطة العســكرية اخلاصــة الثالثــة برقــم ‪ 6054/27/16/3‬وتاريــخ‬\n      ‫‪1433/3/9‬ه ـ ونصهــا نفيدكــم بأنــه مت إبــاغ املدعــى عليــه وتوقيعــه‬\n      ‫علــى اســتالم صــورة لتبليــغ أ‪.‬ه ـ ‪ ،‬وبســؤال املدعــي عــن دعــواه قــرر‬\n      ‫ا لقــد بــاع موكلــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم‬   ‫قائـ ً‬\n      ‫‪ ........................‬ســيارة نــوع ‪ .....‬موديــل ‪ 2008‬رقــم اللوحــة أوراق‬\n      ‫جمركيــة بتاريــخ ‪ 1431/1/12‬بقيمــة إجماليــة قدرهــا أربعــون الــف‬\n      ‫ريــال علــى هيئــة أقســاط شــهرية قــدر كل قســط ألــف ريــال اعتبــار ًا‬\n\n‫‪125‬‬\n\f‫مــن ‪1431/1/25‬ه ـ وقــد أشــترط موكلــي عليــه أنــه يف حالــة تأخــره‬\n‫ا ومــن ذلــك التاريــخ‬  ‫بدفــع ثالثــة أقســاط فــإن املبلــغ حــال الدفــع كامـ ً‬\n‫لــم يصــل موكلــي منهــا شــيئ ًا حتــى اآلن أطلــب إلزامــه بدفــع املبلــغ هــذه‬\n‫دعــواي وبســؤاله البينــة قــال أحضرهــا يف اجللســة القادمــة عليــه رفعــت‬\n‫اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر املدعــى‬\n‫عليــه رغــم تبلغــه باملوعــد لشــخصه مبوجــب اإلفــادة الصــادرة مــن‬\n‫مجموعــة الشــرطة العســكرية اخلاصــة الثالثــة برقــم ‪8127/27/16/3‬‬\n‫وتاريــخ ‪1433/4/3‬ه ـ ونــص املفيــد منــه نفيدكــم بأنــه مت إبــاغ املدعــى‬\n‫عليــه وتوقيعــه علــى اســتالم صــورة التبليــغ أ‪.‬ه ـ ‪ ،‬ولــم يردنــا منــه أي عذر‬\n‫وبســؤال املدعــي وكالــة عــن البينــة قــدم لنــا الورقــة اآلتــي نصهــا أقــر أنــا‬\n‫املوقــع أســمي أدنــاه ‪ ..................‬بأننــي اشــتريت ســيارة نــوع ‪ 2008 ....‬من‬\n‫األخ ‪ ..............‬مببلــغ وقــدره أربعــون ألــف ريــال على هيئة أقســاط شــهرية‬\n‫مقــدار القســط ألــف ريــال اعتبــار ًا مــن ‪1431/1/25‬ه ـ كمــا ال يحق لي‬\n‫تأخيــر أي قســط وإذا تأخــرت ثالثــة أقســاط متتاليــة فإنــي مســتعد بدفع‬\n‫كامــل املبلــغ وعليــه أوقــع املقــر مبــا فيــه ‪ ................‬توقيعــه بصمتــه أ‪.‬ه ـ‬\n‫‪ ،‬ونظــر ًا النتهــاء وقــت اجللســة فقــد رفعــت ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة ‪ ................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ..........‬ولــم يحضــر املدعــى عليــه وبعــرض اليمــن علــى املدعــي أصالــة‬\n‫ا واهلل أن دعــواي ضــد املدعــى عليــه‬            ‫اســتعد بأدائ ــها ثــم حلــف قائ ـ ً‬\n‫‪ ...........‬صحيحــة وأن لــي بذمتــه مبلــغ أربعــن ألــف ريــال حــال الدفــع‬\n‫لــم يصل ــني منــه شــيء ح ــتى اآلن هك ــذا ح ــلف فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى ولكــون املدعــى عليــه تبلــغ لشــخصه ولــم يحضــر ولــم يردنــا‬\n‫ـاء علــى البينــة واليمــن املســتظهرة واســتنادا علــى املــادة‬        ‫منــه عــذر وبنـ ً‬\n\n                                                                                              ‫‪126‬‬\n\f      ‫اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية وملــا ذكــره املجــد‬\n      ‫أبــو البــركات رحمــه اهلل يف محــرره بقولــه ومــن أدعــى علــى غائــب أو‬\n      ‫مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه بينــة ســمعت وحكــم‬\n      ‫لــه ويســتحلفه احلاكــم علــى بقــاء حقــه وملــا تقــدم ذكــره فقــد حكمــت‬\n      ‫علــى املدعــى عليــه ‪ ...........‬أن يســلم للمدعــي ‪ .........‬مبلــغ أربعــن ألــف‬\n      ‫ريـ(‪ )40000‬ــال وقــررت الكتابــة للمدعــى عليــه ألخــذ قناعتــه باحلكــم‬\n      ‫مــن عدمهــا وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                             ‫حــرر يف ‪1433/5/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق‪ 1433/10/22‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 01 : 00‬وكان قــد جــرى منــا الكتابــة ملديــر قســم‬\n      ‫احملضريــن باحملكمــة لتســليم املدعــى عليــه ‪ ...............‬نســخة احلكــم‬\n      ‫لتقــدمي الئحتــه االعتراضيــة مبوجــب كتابنــا رقــم ‪ 33945061‬وتاريــخ‬\n      ‫‪1433/5/26‬ه ـ وحيــث وردنــا اجلــواب مــن قائــد مجموعــة الشــرطة‬\n      ‫العســكرية اخلاصــة الثالثــة مبوجــب كتابــة رقــم ‪19437/27/16/3‬‬\n      ‫وتاريــخ ‪1433/8/24‬ه ـ ونــص املفيــد منــه نفيدكــم بــأن املذكــور‬\n      ‫صــدر لــه قــرار إنهــاء خدمــات مبوجــب القــرار املرفــق رقــم ‪46413‬‬\n      ‫وتاريــخ ‪1433/8/17‬ه ـ اعتبــارا ً مــن تاريــخ ‪1433/5/15‬ه ـ نأمــل العلــم‬\n      ‫واإلحاطــة أ ‪ .‬ه ـ ‪ ،‬وملــا ذكــر واســتناد ًا علــى الفقــرة اخلامســة مــن املــادة‬\n      ‫السادســة والســبعني بعــد املائــة ونصهــا إذا تعــذر تســليم نســخة احلكــم‬\n      ‫الغيابــي إلــى احملكــوم عليــه أو وكيلــه رفــع احلكــم إلــى محكمــة‬\n      ‫التمييــز بــدون الئحــة اعتراضيــة ‪ ،‬وال مينــع مــن ذلــك التمــاس إعــادة‬\n      ‫النظــر وفــق أحكامــه أ ‪.‬ه ـ ‪ ،‬عليــه فقــد قــررت إحالتهــا إلــى محكمــة‬\n      ‫االســتئناف مبنطقــة تبــوك لتدقيقــه وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n\n\n‫‪127‬‬\n\f                             ‫آلــه وصحبــه وســلم حــرر يف ‪1433/10/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد يف يوم الســبت املوافــق‪ 1434/06/10‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي وكالــة ‪...............‬‬\n‫وقــد أحضــر وكالــة جديــدة تتضمــن الرقــم ‪ 570709003205‬يف‬\n‫‪1433/2/17‬ه ـ صــادرة مــن كتابــة العــدل بخميــس مشــيط واملخــول لــه‬\n‫فيهــا حــق اإلقــرار واملرافعــة واملدافعــة ‪ ،‬وكانــت املعاملــة قــد عــادت مــن‬\n‫محكمــة االســتئناف مبنطقــة تبــوك مبوجــب كتــاب فضيلــة رئيســها‬\n‫رقــم ‪ 3462953‬وتاريــخ ‪1434/2/6‬ه ـ ونــص املفيــد منــه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي‪ -1 :‬بعثت املعاملة‬\n‫إلــى محكمــة االســتئناف قبــل اكتمــال إجــراءات تبليــغ احملكــوم‬\n‫عليــه بنســخة احلكــم ‪ -2 .‬مــن أنــواع الشــروط يف عقــد البيــع شــرط‬\n‫فاســد ينــايف مقتضــي العقــد ويصــح معــه البيــع كمــا قــرره أهــل العلــم‬\n‫يف موضعــه لقــول الرســول صلــى اهلل عليــه وســلم((من اشــترط شــرط ًا‬\n‫ليــس يف كتــاب اهلل فهــو باطــل وإن كان مائــة شــرط)) متفــق عليــه‬\n‫وتراضــي الطرفــن علــى هــذا الشــرط ال يصححــه وهــذا ينطبــق علــى‬\n‫الشــرط املذكــور يف العقــد محــل النــزاع ولــذا صــدرت فتــوى اللجنــة‬\n‫الدائمــة لإلفتــاء برئاســة ســماحة الشــيخ ابــن بــاز رحمــه اهلل بأنــه شــرط‬\n‫غيــر صحيــح ألنــه ينفــي مقتضــى العقــد وهــو التأجيــل التــي اســتحقت‬\n‫بــه الزيــادة أ‪.‬ه ـ مجمــوع فتــاوي اللجنــة الدائمــة ‪ 182/13‬واملناســب‬\n‫يف هــذه القضيــة وأمثالهــا أن يحكــم باملبلــغ احلــال بحســب األقســاط‬\n‫كمــا يحكــم بدفــع بقيــة األقســاط يف موعــد حلولهــا حســب مــا جــاء يف‬\n‫العقــد بينهــا‪ .‬فنرغــب إطــاع فضيلــة وتأملــه يف ذلــك واتخــاذ مــا يظهــر‬\n‫لــه وفقــه اهلل وإعــادة املعاملــة إلينــا بعــد ذلــك وبــاهلل التوفيــق ‪ .‬وبعــرض‬\n\n\n                                                                                        ‫‪128‬‬\n\f      ‫املالحظــة الثانيــة علــى املدعــي وكالــة قــال بــأن جميــع املبلــغ قــد حــل‬\n      ‫يف ذمــة املدعــى عليــه ملوكلــي وكان قــد جــرى منــا الكتابــة لشــرطة‬\n      ‫منطقــة تبــوك لإلفــادة عــن عنــوان املدعــى عليــه وحيــث وردنــا اجلــواب‬\n      ‫منهــم مبوجــب كتابهــم رقــم ‪ 13/2292/28‬وتاريــخ ‪1434/5/28‬ه ـ‬\n      ‫ونــص املفيــد منــه نفيــد فضيلتكــم بأنــه مت البحــث عــن املواطــن‬\n      ‫‪ ............‬وأتضــح أنــه يســكن محافظــة صامطــة التابعــة ملنطقــة جيــزان‬\n      ‫أ‪.‬ه ـ ‪ ،‬وبعرضــه أيضــا ً علــى املدعــي وكالــة قــال مــا جــاء يف كتــاب‬\n      ‫مديــر شــرطة منطقــة تبــوك صحيــح ولكنــه أثنــاء إقامــة الدعــوى كان‬\n      ‫املدعــى عليــه يســكن تبــوك وهــو مــا زال يســكنها إال أنــه يتهــرب‬\n      ‫عــن احلضــور وحســبي اهلل ونعــم الوكيــل ‪ ،‬كمــا أحيــط أصحــاب‬\n      ‫الفضيلــة ‪ -‬ســلمهم اهلل ‪ -‬بأنــه ال زيــادة مقابــل التأجيــل بحيــث ينطبــق‬\n      ‫مــا ذكــر وإمنــا هــي مســالة اشــتراط البائــع باألصــل حلــول األقســاط‬\n      ‫قبــل موعدهــا عنــد تأخــر املدعــي عــن اداء بعضهــا مــادام املديــن قــد‬\n      ‫رضــي بهــذا الشــرط عنــد التعاقــد وهــذا مــا نــص علــى جــوزاه يف مجمــع‬\n      ‫الفقــه اإلســامي يف دورتــه املنعقــدة يف مؤمتــره الســادس مبحافظــة‬\n      ‫جــده باململكــة العربيــة الســعودية وعليــه فقــد قــررت إعــادة كامــل‬\n      ‫أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة تبــوك لتدقيقــه وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                               ‫يف ‪1434/6/10‬ه ـ ‪.‬‬\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34262550‬وتاريــخ‬\n                                                        ‫‪1434/7/9‬هـ‪.‬‬\n\n\n\n‫‪129‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":124,"source_page_end":129,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32ccc814a52f4aa00b2ea5c2b04301cfc897e5d72b0f8a1dc2705ae1a3956e7c","normalized_text_hash":"e123609dae23244c2d014bda4ad5b57c7a71b55060a2b7df5207212cc56883cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p124-33251132"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d70ee2bf-cc13-5a00-8c9c-60edcfa8f41f","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -املطالبة بإعادة قيمة تذاكر -عدم حضور املدعى عليه - احلكم غيابي ا بإعادة ثمن التذاكر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33152564","case_number":"8603","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/26","year":"1434","subject":"بيع -املطالبة بإعادة قيمة تذاكر -عدم حضور املدعى عليه - احلكم غيابي ا بإعادة ثمن التذاكر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/3/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33152564 :‬‬\n                        ‫َر ْق ُم الدعوى‪8603 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34229126‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n‫بيــع ‪ -‬املطالبــة بإعــادة قيمــة تذاكــر‪ -‬عــدم حضــور املدعــى عليــه ‪-‬‬\n‫احلكــم غيابيـ ًا بإعــادة ثمــن التذاكــر ‪ -‬رفــع احلكــم حملكمة االســتئناف‬\n                                  ‫لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n                  ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بأنــه مت إيــداع مبلــغ مالــي يف حســاب املدعــى‬\n‫عليــه قيمــة تذاكــر ســفر ‪ -‬لــم يتــم تســليم هــذه التذاكــر ‪ -‬طلــب‬\n‫املدعــي احلكــم غيابي ـ ًا علــى املدعــى عليــه بإعــادة املبلــغ املذكــور‬\n‫قيمــة التذاكــر ‪ -‬قامــت احملكمــة باالســتيثاق مــن اإليــداع عــن طريــق‬\n‫ا بنكيـ ًا‬‫مؤسســة النقــد ‪ -‬كمــا أن املدعــي قــدم لصحــة دعــواه حتويـ ً‬\n‫وقــام بحلــف اليمــن ‪ -‬لــذا حكمــت احملكمــة غيابي ـ ًا بإلــزام املدعــى‬\n‫عليــه بدفــع قيمــة تذاكــر الســفر املودعــة ‪ -‬الغائــب علــى حجتــه متــى‬\n                        ‫حضــر ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                ‫‪82‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 8603‬وتاريــخ ‪ 1429/02/18‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 2925769‬وتاريــخ ‪ 1429/02/18‬ه ـ ففــي يــوم األحــد‬\n     ‫املوافق‪ 1432/10/13‬هـ افتتحت اجللسة الساعة ‪ 12 : 57‬وفيها حضر‬\n     ‫‪ .............‬ســجل رقــم ‪ .............‬بالوكالــة عــن ‪ ...........‬بالوكالــة رقــم‬\n     ‫‪ 9484‬يف ‪ 1429/01/25‬ه ـ الصــادرة مــن كتابــة العدل الثانية يف شــرق‬\n     ‫الريــاض ولــم يحضــر املدعــى عليــه ‪ ...........‬ســجل رقــم ‪1001661253‬‬\n     ‫وقــد جــرى تبليغــه عــن طريــق وزارة الداخليــة باخلطاب رقــم‪321158565‬‬\n     ‫وقــد جــرى حتديــد موعــد جديــد يــوم األحــد املوافــق ‪ 1432/11/25‬ه ـ‬\n     ‫ويف يــوم الثالثــاء املوافــق ‪ 1432/11/27‬ه ـ حضــر املدعــي وكالــة ولــم‬\n     ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وبســؤال املدعــي عــن دعــواه قــال‬\n     ‫إنــه يف تاريــخ ‪ 2007/04/14‬مت إيــداع مبلــغ ثالثمائــة وثمانيــة وخمســن‬\n     ‫ألفــا وأربعمائــة وثمانيــة وثمانــن ريــاال يف حســابه وذلــك قيمــة تذاكــر‬\n     ‫ســفر ولــم يتــم تســليم موكلــي هــذه التذاكــر حيــث أنــه اختفــى ونظــرا‬\n     ‫ألن فضيلتكــم طلــب مــن مؤسســة النقــد التأكــد مــن صحــة اإليــداع‬\n     ‫ومت ذلــك وحيــث أننــا تعبنــا مــن املراجعــة والبحــث عنــه أكثــر مــن ثــاث‬\n     ‫ســنوات دون العثــور عليــه ومت حتديــد ثــاث جلســات دون حضــوره لــذا‬\n     ‫أطلــب مــن فضيلتكــم احلكــم علــى املدعــى عليــه باملبلــغ املدعــى بــه‬\n     ‫غيابيــا هكــذا ادعــى وبســؤاله البينــة علــى دعــواه قــال لــدي البينــة‬\n     ‫وســوف أحضرهــا يف اجللســة القادمــة وعليــه رفعــت اجللســة وحــدد لهــا‬\n\n‫‪83‬‬\n\f‫موعــد يــوم االثنــن املوافــق ‪ 1433/01/24‬ه ـ ويف يــوم االثنــن املوافــق‬\n‫‪ 1433/01/24‬ه ـ حضــر املدعــي وكالــة وبســؤاله عــن البينــة التــي وعد‬\n‫بهــا أبــرز طلــب حتويــل علــى ‪ .........‬بتاريــخ ‪ 2007/04/14‬مببلــغ وقــدره‬\n‫ثالثمائــة وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال وقــال‬\n‫إن هــذه هــي بينتــي وال يوجــد لــدى موكلــي بينــة أخــرى وقــد جــرى‬\n‫االستفســار عــن هــذه احلوالــة فوردنــا خطــاب مؤسســة النقــد رقــم ‪1508‬‬\n‫ن ظ ‪ /‬أ ق يف ‪ 1432/07/06‬هـ واملتضمن أن احلوالة صحيحة وصادرة‬\n‫مــن حســاب املدعــي لصالــح حســاب املدعــى عليه بتاريــخ ‪2007/04/14‬‬\n‫ا‪.‬ه ـ عنــد ذلــك طلبــت مــن املدعــي إحضــار موكلــه يف اجللســة القادمــة‬\n‫ألداء اليمــن علــى صحــة دعــواه فاســتعد بذلــك وعليــه رفعــت اجللســة‬\n‫وحــدد لهــا موعــد يــوم األربعــاء ‪1433/03/23‬ه ـ ويف يــوم األربعــاء‬\n‫املوافــق‪ 1433/03/23‬ه ـ حضــر املدعــي وكالــة وحضــر حلضــوره‬\n‫املدعــي أصالــة ‪ ............‬ســجل رقــم ‪ .........‬وبعــرض اليمــن عليــه حلــف‬\n‫قائــا واهلل العظيــم إننــي حولــت للمدعــى عليــه ‪ ..............‬مبلغــا وقــدره‬\n‫ثالثمائــة وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال يف‬\n‫حســابه وذلــك قيمــة تذاكــر ســفر ولكنــه لــم يســلم لــي التذاكــر حتــى‬\n‫اآلن ولــم يعــد لــي املبلــغ وال جــزءا منــه واهلل هكــذا حلــف فبنــاء علــى مــا‬\n‫ســبق مــن الدعــوى وخطــاب مؤسســة النقــد وحلــف املدعــي اليمــن طبــق‬\n‫مــا طلــب منــه لــذا فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره ثالثمائــة‬\n‫وثمانيــة وخمســون ألفــا وأربعمائــة وثمانيــة وثمانــون ريــاال للمدعــي‬\n‫وبذلــك حكمــت وهــو حكــم غيابــي خاضــع لتعليمــات التمييــز والغائب‬\n‫علــى حجتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/03/23‬ه ـ‬\n\n\n                                                                                        ‫‪84‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n     ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n     ‫من فضيلة رئيس احملكمة العامة بالرياض املساعد برقم ‪32624884‬‬\n     ‫وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n     ‫باحملكمــة الشــيخ‪ ................./‬املســجل برقــم ‪ 33152564‬وتاريــخ‬\n     ‫‪1433/3/26‬ه ـ اخلــاص بدعوى‪........./‬وكالــة ضــد‪.........../‬يف مبلــغ من‬\n     ‫املــال علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم فضيلتــه كمــا‬\n     ‫هــو موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم‬\n     ‫يظهــر مــا يوجــب االعتــراض علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪85‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":82,"source_page_end":85,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"45241451d8e795fdc2ef63dfc1acf58cc323ec8a07626385cc5f9100a2b17c8a","normalized_text_hash":"e6187a74f941c120fc7f2da2c2f6fbc5ac8bb23e5ae4a4ae65a292766a080f11","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p82-33152564"},{"id":"5440111b-2f01-56b1-b98b-d207781b7386","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عربون -دفع للوسيط كداللة مقابل التوسط يف شراء فيا -الرجوع يف الشراء -املطالبة برد مبلغ الداللة -رفض رد املبلغ -املبلغ املدفوع عربون وليس داللة -مصادقة املدعي على السند املرفق باملعاملة بأن املبلغ عربون -رد دعوى املدعي وإخاء سبيل املدعى عليه من الدعوى .","document_number":"34229820","case_number":"31922","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"بيع -عربون -دفع للوسيط كداللة مقابل التوسط يف شراء فيا -الرجوع يف الشراء -املطالبة برد مبلغ الداللة -رفض رد املبلغ -املبلغ املدفوع عربون وليس داللة -مصادقة املدعي على السند املرفق باملعاملة بأن املبلغ عربون -رد دعوى املدعي وإخاء سبيل املدعى عليه من الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34229820 :‬‬\n                      ‫َر ْق ُم الدعوى‪31922 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34331655‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n‫بيــع ‪ -‬عربــون ‪ -‬دفــع للوســيط كداللــة مقابــل التوســط يف شــراء فيــا‬\n‫‪ -‬الرجــوع يف الشــراء ‪ -‬املطالبــة بــرد مبلــغ الداللــة ‪ -‬رفــض رد املبلــغ‬\n‫‪ -‬املبلــغ املدفــوع عربــون وليــس داللــة ‪ -‬مصادقــة املدعــي علــى الســند‬\n‫املرفــق باملعاملــة بــأن املبلــغ عربــون ‪ -‬رد دعــوى املدعــي وإخــاء ســبيل‬\n                                                ‫املدعــى عليــه مــن الدعــوى ‪.‬‬\n\n\n\n                            ‫‪ -1‬قوله تعالى (بل اإلنسان على نفسه بصيرة) ‪.‬‬\n                                              ‫‪ -2‬قاعدة ‪ :‬ال عذر ملن ّأقر ‪.‬‬\n\n\n\n‫قــام املدعــي بدفــع مبلــغ داللــة إلــى املدعــى عليــه مقابــل وســاطته يف‬\n‫شــراء فيــا لــه‪ ،‬طلــب املدعــي مــن املدعــى عليــه تخفيــض ثمــن الفيــا‬\n‫لوجــود إصالحــات جوهريــة بهــا‪ ،‬رفــض املدعــى عليــه ذلــك بحجــة أن‬\n‫املبلــغ املدفــوع عربــون وليــس مقابــل داللــة وقــد ســلمه للمالــك‪ ،‬وقــدم‬\n‫ا علــى ذلــك ســند القبــض مبينـ ًا بــه أن املبلــغ املدفــوع‬ ‫املدعــى عليــه دليـ ً‬\n‫عربون ـ ًا للشــراء‪ ،‬أقّ ــر املدعــي بصحــة الســند إال أنــه لــم ينتبــه إلــى مــا‬\n‫وجــد بــه‪ ،‬حكمــت احملكمــة بــرد الدعــوى واخــاء ســبيل املدعــى‬\n‫عليــه مــن الدعــوى ‪ -‬اعتــرض املدعــي ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                       ‫االســتئناف ‪.‬‬\n                                                                                         ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض املســاعد برقــم ‪ 31922‬وتاريــخ ‪1431/07/04‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 31123171‬وتاريــخ ‪1431/07/04‬ه ـ ففــي‬\n     ‫يــوم األربعــاء املوافــق ‪1433/10/25‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n     ‫‪ 08‬وفيهــا حضــر ‪ .........‬مبوجــب ســجل مدنــي رقــم ‪ ...........‬وادعــى علــى‬\n     ‫احلاضــر معــه ‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...............‬بصفتــه‬\n     ‫وكيــا عــن‪ .........‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...........‬ينــوب عنــه‬\n     ‫يف املطالبــة واملرافعــة واملدافعــة واإلنــكار واإلقــرار والصلــح وقبــول‬\n     ‫األحــكام ونفيهــا مبوجــب صــك وكالــة صــادر مــن كتابــة العــدل‬\n     ‫الثانيــة بشــرق الريــاض رقــم ‪ 33317217‬يف‪1433/10/18‬ه ـ قائــا يف‬\n     ‫حتريــر دعــواه عليــه ســبق أن اشــتريت مــن ‪.............‬فيــا يف حــي احلمــراء‬\n     ‫وكان املدعــى عليــه وســيطا بينــي وبينــه وســلمت املدعــى عليــه شــيكا‬\n     ‫باســمه مببلــغ وقــدره خمســة وســبعون ألــف ريــال للداللــة وبعــد ذلــك‬\n     ‫طلبــت مــن املدعــى عليــه تخفيــض قيمــة الفيــا ألن فيهــا أشــياء جوهريــة‬\n     ‫حتتــاج إلــى مبالــغ طائلــة لتعديلهــا فأخبرنــي بــأن املالــك رفــض ذلــك‬\n     ‫فطلبــت منــه إرجــاع مبلــغ الداللــة فرفــض أطلــب إلزامــه بإرجاعــه هــذه‬\n     ‫دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n     ‫مــن أن موكلــي كان وســيط يف بيــع الفيــا وأنــه اســتلم منــه املبلــغ‬\n     ‫املذكــور فصحيــح إال أن املبلــغ كان عربونــا لشــراء الفيــا وقــد اســتلم‬\n     ‫صاحــب العقــار العربــون وقــد ســبق أن صــدر صــك مــن ديــوان املظالــم‬\n\n‫‪87‬‬\n\f‫بصــرف النظــر عــن دعــوى املدعــي والتــي ادعــى فيهــا أن املبلــغ الــذي‬\n‫دفعــه لنــا كان عربــون لــذا أطلــب صــرف النظــر عــن دعــوى املدعــي‬\n‫هكــذا أجــاب ثــم أبــرز املدعــى عليــه صــورة ســند قبــض علــى مطبوعات‬\n‫شــركة ‪ .................‬املتضمــن اســتالم املبلــغ املذكــور مــن املدعــي‬\n‫وذلــك عــن قيمــة عربــون شــراء فيــا باحلمــراء لقيمــة ثالثــة مليــون ريــال‬\n‫مســاحة ‪1125‬م ثــم أبــرز ورقــة عاديــة موقــع عليهــا مــن قبــل ‪..............‬‬\n‫تتضمــن اســتالمه للمبلــغ مــن املدعــى عليــه ثــم أبــرز صــورة احلكــم رقــم‬\n‫‪/60‬د‪/‬ف‪ 2/‬لعــام ‪ 1431‬الصــادر مــن ديــوان املظالــم فوجدتــه مطابقــا‬\n‫ملــا ذكــر وبســؤال املدعــي هــل لديــه بينــة علــى أن املبلــغ املذكــور‬\n‫داللــة أجــاب قائــا ليــس لــدي بينــة ســوى أن مبلــغ يســاوي قيمــة الداللــة‬\n‫املتعــارف عليهــا يف الســوق هكــذا أجــاب وبعــرض ميــن املدعــى عليــه‬\n‫أصالــة علــى املدعــي قبــل بهــا لــذا أمــرت بطلــب حضــور املدعــى عليــه‬\n                                                               ‫أصالــة ألداء اليمــن‬\n‫ويف جلســة أخــرى حضــر املدعــي واملدعــى عليــه أصالة ‪ .............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬وبســؤال املدعــى عليــه‬\n‫أصالــة عمــا ذكــره املدعــي أصالــة مــن أنهــا عربــون للفلــة وليســت ســعي‬\n‫قــال‪ :‬أنهــا عربــون وقــد ســلمت صاحــب الفيــا هــذا العربــون وبقيــت‬\n‫الفيــا ملــدة شــهرين لــم تبــاع وحــن تأخــر املدعــي عــن دفــع قيمــة الفيــا‬\n‫قــام صاحــب الفيــا ببيعهــا وقــد ســلمت صاحــب الفيــا املبلــغ بنــاء علــى‬\n‫ســند صــرف رقــم ‪ 157‬والــذي دفعــت لــه مبوجبــه هــذا املبلــغ هكــذا‬\n‫أجــاب؛ لــذا طلبــت إدخــال صاحــب الفيــا ‪ .......................‬يف الدعــوى‬\n‫ويف جلســة أخــرى لــدي أنــا ‪............‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم األحــد املوافــق‪ 1434/06/04‬ه ـ افتتحــت اجللســة‬\n\n\n                                                                                       ‫‪88‬‬\n\f     ‫الســاعة ‪ 09.30‬وفيهــا حضــر املدعــي اصالــة واملدعــى عليــه وكالــة‬\n                           ‫‪ ........‬املــدون هوياتهمــا ووكالــة املدعــى عليــه ســابقا‬\n     ‫وبتــاوة مــا جــرى ضبطــه صادقــا عليــه وبســؤال املدعــي اصالــة عن ســند‬\n     ‫القبــض رقــم ‪ 0050‬يف ‪1430/11/20‬ه ـ واملرفــق نســخة منــه باملعاملــة‬\n     ‫قــال هــذا الســند هــو الــذي ســلم لــي وهــو مطابــق ملــا لديكــم وباالطــاع‬\n     ‫عليــه وجدتــه متضمنــا مــا نصــه ‪ ( :‬وذلــك قيمــة عربــون شــراء فيــا‬\n     ‫باحلمــراء بقيمــة ‪ 3.000.000‬ثالثــة مليــون ريــال مســاحة ‪1125‬م ) أ‪.‬ه ـ‬\n     ‫وبعرضــه علــى املدعــي وهــو أكادميــي يف جامعــة امللــك ســعود يحمــل‬\n     ‫شــهادة الدكتــوراه أجــاب بقولــه لــم انتبــه ملــا كتــب يف الســند وأنــا قليــل‬\n     ‫خبــرة يف مثــل هــذه األمــور علمــا انــه هــو الــذي كتــب محتــوى الســند‬\n     ‫هــذه إجابتــي وبعــد االطــاع علــى مــا ســبق ضبطــه من الدعــوى واإلجابة‬\n     ‫واإلقــرار املدعــي بصحــة الســند وال عــذر ملــن أقــر ولعمــوم قولــه تعالــى‬\n     ‫( بــل اإلنســان علــى نفســه بصيــرة ) وملشــروعية بيــع العربــون بــأن يقــول‬\n     ‫ـزاء مــن قيمــة املبيــع فــإن أتيتــك بباقــي القيمــة‬‫املشــتري للبائــع خــذ جـ ً‬\n     ‫وإال فهــو لــك وألن املفــرط أولــى باخلســارة ولــم احتــج ميــن املدعــى عليــه‬\n     ‫اصالــة علــى إنــكار الدعــوى لعــدم وجــود احلاجــة إليــه بعــد مصادقــة‬\n     ‫املدعــي علــى الســند املرفــق باملعاملــة وجلميــع مــا تقــدم فقــد حكمــت‬\n     ‫بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‬\n     ‫وبعرضــه علــى املدعــي قــرر عــدم القناعــة فجــرى تســليمه نســخة مــن‬\n     ‫إعــام احلكــم وأفهمتــه بــأن لــه إبــداء اعترضــه عليــه خــال ثالثــن‬\n     ‫يومـ ًا مــن تاريــخ اســتالم نســخة احلكــم تنتهــي يف ‪1434/07/04‬ه ـ فــإن‬\n     ‫مضــت املــدة دون تقــدمي الالئحــة االعتراضيــة ســقط حقــه يف االعتــراض‬\n     ‫واكتســب احلكــم القطعيــة وذلــك اســتناد ًا للمــواد رقــم ‪176‬و‪ 178‬مــن‬\n\n\n‫‪89‬‬\n\f                ‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ففهــم ذلــك‬\n‫أمــا املدعــى عليــه فلــم يتــم عــرض احلكــم عليــه اســتنادا للمــادة ‪147‬‬\n‫مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/04‬ه ـ والســاعة‬\n                                                                     ‫‪. 10.00‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34331655‬وتاريــخ‬\n                                              ‫‪1434/10/15‬هـ‪.‬‬\n\n\n\n\n                                                                                   ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":86,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9e3cda29e6b606d8c9641396956d784e378a3fd92f7503b36f5acde38d33a610","normalized_text_hash":"89ad6df4ab9016a21a21e743226400088d5ba15d398ea2e1e098f7ce681aa34a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p86-34229820"},{"id":"8a3c1390-f5c1-5d18-93e8-f14a36cc389b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع فيا وعدم قبض كامل الثمن -بينة املدعي صك سابق بأحقيته يف املبلغ -إلزام املدعى عليه بدفع الثمن .","document_number":"33192371","case_number":"34173","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/14","year":"1434","subject":"بيع -بيع فيا وعدم قبض كامل الثمن -بينة املدعي صك سابق بأحقيته يف املبلغ -إلزام املدعى عليه بدفع الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/4/14 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33192371 :‬‬\n                           ‫َر ْق ُم الدعوى‪34173 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3410470‬تاريخه‪1434/1/12 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬بيــع فيــا وعــدم قبــض كامــل الثمــن ‪ -‬بينــة املدعــي صــك‬\n           ‫ســابق بأحقيتــه يف املبلــغ ‪ -‬إلــزام املدعــى عليــه بدفــع الثمــن ‪.‬‬\n\n\n\n\n                       ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه اشــترى منــه فيــا‪ ،‬قــام املدعــى عليــه‬\n     ‫بســداد جــزء مــن املبلــغ‪ ،‬طالــب املدعــي إلــزام املدعــى عليــه بســداد باقــي‬\n     ‫الثمــن ‪ ،‬دفــع املدعــى عليــه بســداد كامــل الثمــن‪ ،‬قــام املدعــي بإبــراز‬\n     ‫صــك ســابق علــى موضــوع الدعــوى يفيــد بــأن املبلــغ محــل اخلــاف مــن‬\n     ‫حــق املدعــي ‪ -‬لــذا فقــد ثبــت أن بذمــة املدعــى عليــه للمدعــي مبلــغ مائتي‬\n     ‫ألــف ريــال وألزمتــه بســدادها وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n                    ‫عــدم القناعــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪97‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 43173‬وتاريــخ ‪1431/10/12‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 31169092‬وتاريــخ ‪1431/10/12‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق ‪1433/01/08‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 13‬‬\n‫وقــد ســبق وأن حــدد لهمــا موعــد يــوم األربعــاء ‪1432/02/08‬ه ـ الســاعة‬\n‫‪ 10 : 30‬ثــم حــدد لهمــا موعــد يــوم األحــد ‪1432/06/05‬ه ـ الســاعة ‪30‬‬\n‫‪ 09 :‬ثــم حــدد لهمــا موعــد يــوم األحــد ‪1432/07/10‬ه ـ الســاعة ‪: 15‬‬\n‫‪ 10‬ثــم حــدد لهمــا موعــد هــذا اليــوم ‪1433/01/08‬ه ـ الســاعة ‪10 : 00‬‬\n‫ولــم يســتلم املدعــى عليــه التبليــغ إال التبليــغ لهــذه اجللســة وأول جلســة‬\n‫ويف هــذا اليــوم حضــر ‪ ............‬ســجل مدنــي رقــم ‪ ........‬وادعــى علــى‬\n‫ا يف دعــواه عليــه ‪:‬‬‫احلاضــر معــه ‪ .............‬ســجل مدنــي رقــم ‪ ...........‬قائـ ً‬\n‫لقــد اشــترى املدعــى عليــه منــي الفيــا الواقعــة يف حــي املنــار واململوكــة‬\n‫بالصــك رقــم ‪ 510108004257‬مببلــغ قــدره مليــون وســتمائة ألــف ريــال‬\n‫بتاريــخ ‪1428/02/20‬ه ـ ســلم مــن القيمــة مبلــغ قــدره مليــون وأربعمائــة‬\n‫ألــف ريــال وبقــي مبلــغ قــدره مائتــان ألــف ريــال لــم يســلمها أطلــب احلكــم‬\n‫علــى املدعــى عليــه بدفــع هــذا املبلــغ لــي هــذه دعــواي وبعرضهــا علــى‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬أطلــب مهلــة لإلجابــة وأجيــب لطلبــه ويف‬\n‫جلســة أخــرى لــدي أنــا ‪ ...............‬القاضــي باحملكمــة العامــة بالريــاض‬\n‫ففــي يــوم األربعــاء املوافــق ‪1433/04/14‬ه ـ فتحــت اجللســة الســاعة‬\n‫‪ 12 : 00‬وقــد انتقــل فضيلــة القاضــي ناظــر القضيــة الســابق عــن‬\n\n                                                                                          ‫‪98‬‬\n\f     ‫العمــل بهــذه احملكمــة وجــرى تكليفنــا بالعمــل بهــذا املكتــب وقــررت‬\n     ‫إكمــال نظــر الدعــوى اســتناد ًا للمــادة (‪ )166‬مــن نظــام املرافعــات هــذا‬\n     ‫وقــد حضــر يف هــذه اجللســة املدعــي أصالــة واملدعــى عليــه أصالــة وجــرى‬\n     ‫عــرض الدعــوى علــى املدعــي فأقــر بــأن هــذه دعــواه وبعــرض الدعــوى‬\n     ‫علــى املدعــى عليــه قــال ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن أننــي اشــتريت‬\n     ‫منــه املنــزل املذكــور بالثمــن املذكــور فهــذا كلــه صحيــح وأمــا مــا‬\n     ‫ذكــره مــن الواصــل فهــو غيــر صحيــح والصحيــح أننــي ســلمت الثمــن‬\n     ‫ا وليــس يف ذمتــي للمدعــي أي مبلــغ هكــذا أجــاب وبعــرض ذلــك‬        ‫كامـ ً‬\n     ‫علــى املدعــي قــال‪ :‬الصحيــح مــا ذكــرت وبســؤال املدعــى عليــه عــن‬\n     ‫البينــة علــى التســليم قــال ‪ :‬بينتــي ضبــط املبايعــة لــدى كتابــة العــدل‬\n     ‫حيــث قــرر املدعــي أنــه اســتلم كامــل الثمــن هكــذا قــال وبعــرض ذلــك‬\n     ‫علــى املدعــي قــال ‪ :‬مــا ذكــره صحيــح ولكــن كان إقــرار ًا صوري ـ ًا‬\n     ‫بخصــوص الثمــن مــن أجــل اإلفــراغ وقــد أقــام املدعــى عليــه دعــوى بعــد‬\n     ‫املبايعــة يطالبنــي فيهــا بقيمــة األثــاث الــذي كان موجــود ًا يف املنــزل‬\n     ‫وقــت املبايعــة يدعــي فيهــا بأنــه مــن ضمــن املبايعــة وقــد ذكــر يف دعــواه‬\n     ‫أنــه لــم يســلم مــن الثمــن إال املبلــغ الــذي ذكــرت وهــذه الدعــوى الحقــة‬\n     ‫باإلفــراغ ممــا يــدل علــى أن إقــراري باســتالم كامــل الثمــن كان إقــرار ًا‬\n     ‫صوريـ ًا وقــد انتهــت الدعــوى باحلكــم الصــادر مــن هــذه احملكمــة برقــم‬\n     ‫‪ 17/43‬وتاريــخ ‪1430/11/23‬ه ـ ‪ ،‬وختمــت اجللســة لضيــق الوقــت‬\n     ‫حلضــور وقــت الصــاة ‪ ،‬وختمــت اجللســة الســاعة ‪ ، 12 : 15‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وبعــد أداء الصــاة مــن نفــس اليــوم فتحــت اجللســة وحضــر‬\n     ‫فيهــا املدعــي واملدعــى عليــه و أبــرز املدعــي صــك احلكــم الصادر املشــار‬\n     ‫إليــه وقــد جــاء يف دعــوى وكيــل املدعــي مــا نصــه «لقــد اشــترى موكلــي‬\n\n\n‫‪99‬‬\n\f‫مــن املدعــى عليــه الفلــه الواقعــة بحــي املنــار بالريــاض مببلــغ قــدره مليــون‬\n‫وســتمائة ألــف ريــال ومعهــا كامــل األثــاث املوجــود يف الفلــه مــا عــد‬\n‫غــرف النــوم علــى أن يكــون اســتالم الفلــه يف ‪1428/06/17‬ه ـ وقــد مت‬\n‫إفــراغ الصــك إلــى موكلــي مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n‫الريــاض برقــم ‪ 510108004257‬وســلم موكلــي للمدعــى عليــه عنــد‬\n‫إفراغهــا مليــون وأربعمائــة ألــف ريــال وقــد ســلم قبــل ذلــك مبلــغ قــدره‬\n‫مائتــا ألــف ريــال للمدعــى عليــه يف عــام ‪1427‬ه ـ عندمــا أراد أن يشــتري‬\n‫الفلــه يف هــذا العــام وبعــد أن عجــز موكلــي عــن دفــع كامــل املبلــغ قــرر‬\n‫االتفــاق الــذي تضمــن بيــع املدعــى عليــه ملوكلــي الفلــه مببلــغ مليــون‬\n                                                ‫وســتمائة ألــف مــع األثــاث» إ‪.‬ه ـ‬\n‫كمــا وجــدت مــن ضمــن الدفوعــات اخلــاف علــى مبلــغ مائتــي ألــف‬\n‫ريــال والــذي ســلمه املدعــى عليــه كعربــون يف اتفــاق ســابق علــى شــراء‬\n‫البيــت محــل الدعــوى حســب إفــادة املدعــي فســألت املدعــى عليــه هــل‬\n‫هــذا املبلــغ املذكــور يف الصــك هــو مــن ضمــن الواصــل الــذي يذكــره‬\n‫قــال ‪ :‬نعــم إنــه مــن ضمــن الواصــل هــذا وقــد تضمــن الصــك املذكــور‬\n‫قــول فضيلــة ســلفنا مــا نصــه «وبعــرض اليمــن علــى املدعــى عليــه اســتعد‬\n‫ا ‪ :‬واهلل العظيــم الــذي ال إلــه غيــره أن مبلــغ املائتي‬\n                                                          ‫بأدائهــا ثــم حلــف قائـ ً‬\n‫ألــف املدفوعــة قبــل االتفاقيــة غيــر داخلــة ضمــن مبلــغ االتفاقيــة احملــررة‬\n‫ـاء عليــه فقــد ثبــت لــدي ذلــك» إ‪.‬ه ـ‬‫يف عــام ‪1428‬ه ـ هكــذا حلــف فبنـ ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬  ‫‪ ،‬فبنـ ً‬\n‫بشــرائه للمنــزل املذكــور بالثمــن املذكــور وأنكــر الواصــل ودفــع بأنــه‬\n‫قــد ســلم كامــل القيمــة وحيــث قــرر املدعــى عليــه أن مــن ضمــن املبلــغ‬\n‫الواصــل الــذي يذكــره مبلــغ مائتــي ألــف ريــال وأنــه هــو املبلــغ الــذي‬\n\n\n                                                                                         ‫‪100‬‬\n\f      ‫حصــل فيــه اخلــاف بــن الطرفــن يف القضيــة احملكــوم بهــا يف الصــك‬\n      ‫املشــار إليــه أعــاه ونظــر ًا ملــا قــرره فضيلــة مصــدر الصــك مــن أن ذلــك‬\n      ‫املبلــغ لــم يكــن مــن ضمــن مبلــغ االتفاقيــة والتــي تضمنــت عقــد املبايعــة‬\n      ‫بــن الطرفــن لــذا فقــد ثبــت لــدي أن بذمــة املدعــى عليــه للمدعــي مبلــغ‬\n      ‫مائتــي ألــف ريــال وألزمتــه بســدادها وحكمــت بذلــك وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة‬\n      ‫االســتئناف فجــرى تســليمه نســخة مــن احلكــم وأفهــم بــأن عليــه تقــدمي‬\n      ‫الالئحــة االعتراضيــة خــال املــدة احملــددة ‪ ،‬وختمــت اجللســة الســاعة‬\n      ‫‪ ، 01 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪1433/04/14‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1433/0 1/09‬ه ـ‬\n      ‫فتحــت اجللســة الســاعة العاشــرة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالريــاض وبرفقهــا القــرار رقــم ‪ 33308070‬وتاريــخ‬\n      ‫‪1433/06/21‬ه ـ واملتضمــن أنــه لوحــظ مــا يلــي ‪ ( :‬أوال ذكــر املدعــي‬\n      ‫يف الصــك الســابق رقــم ‪ 17/43‬عنــد جوابــه علــى الدعوى املرفوعة ضده‬\n      ‫حــول األثــاث أن هــذا املبلــغ مقابــل األثــاث الــذي لــم يســلمه وهــذا إقــرار‬\n      ‫صريــح مؤاخــذ بــه فعلــى فضيلتــه مناقشــته مع طريف الدعــوى وإجراء ما‬\n      ‫يلــزم نحــوه ثانيــا ‪ :‬لــم يرفــق فضيلتــه صــورة مــن صــك اإلفــراغ ولــم يجــري‬\n      ‫اإليجــاب الشــرعي نحــو مــا دفــع بــه املدعــى عليــه مــن إقــرار املدعــي‬\n      ‫باســتالم كامــل القيمــة والبــد مــن ذلــك فعلــى فضيلتــه مالحظــه مــا‬\n      ‫ذكــر ) أ‪.‬ه ـ نصــه وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة بخصــوص‬\n      ‫امللحوظــة الثانيــة نقــول أنــه مت إجــراء اإليجــاب الشــرعي حســب مــا‬\n      ‫يتضــح مــن وقائــع املرافعــة وقــد أقــر بــه املدعــي إال أنــه دفــع بــأن ذلــك‬\n\n\n‫‪101‬‬\n\f‫اإلقــرار باســتالم القيمــة كان إقــرار صوريــا وأن بينتــه هــي دعــوى‬\n‫املدعــى عليــه بعــد ذلــك أمــا بخصــوص امللحوظــة األولــى فقــد حضــر‬\n‫يف هــذه اجللســة املدعــي كمــا حضــر ‪ ........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن املدعــى عليــه مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل شــرق الريــاض الثانيــة برقــم ‪33282059‬‬\n‫وتاريــخ ‪1433/09/23‬ه ـ وبعــرض مــا جــاء يف الصــك الســابق مــن إقــرار‬\n‫املدعــي بــأن املبلــغ الباقــي هــو مقابــل األثــاث عليــه والــذي أشــار إليــه‬\n‫أصحــاب الفضيلــة فقــال إن مــا ذكرتــه هــو حكايــة عــن مــا قالــه‬\n‫املدعــى عليــه لــي وليــس علــى ســبيل املوافقــة عليــه هكــذا قــال وبعــد‬\n‫الرجــوع إلــى نــص كالم املدعــي املشــار إليــه وجــدت أنــه ممــا يــدل علــى‬\n‫صحــة مــا ذكــره مــن أن ذكــره لذلــك هــو علــى ســبيل احلكايــة أنــه قــد‬\n‫ذكــر يف تتمــة كالمــه أنــه اتصــل عليــه املدعــو ‪ ........‬وطلــب منــه أن‬\n‫يكــون األثــاث مببلــغ خمســة وســبعني ألــف ريــال وأنــه رفــض ذلــك وهــذا‬\n‫يــدل علــى عــدم إقــراره بــأن املبلــغ الباقــي هــو مقابــل األثــاث هــذا وقــد‬\n‫أضــاف املدعــي بقولــه إن كامــل األثــاث موجــود لــدي ومســتعد بتســليمه‬\n‫للمدعــى عليــه هكــذا قــال وحيــث األمــر مــا ذكــر لــم يظهــر لــي مــا‬\n‫يوجــب العــدول عمــا حكمــت بــه‪ .‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                         ‫محمــد وعلــى ألــه وســلم حــرر يف ‪1433/10/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء ‪1433/12/22‬هـ فتحت‬\n‫اجللســة الســاعة ‪ 09.00‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وبرفقهــا القــرار رقــم ‪ 33460003‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫واملتضمــن (أنــه بدراســة مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة وجــد‬\n‫لألكثريــة أنــه غيــر مقنــع إلقــرار املدعــي باســتالم املبلــغ احملكــوم بــه‬\n\n\n                                                                                       ‫‪102‬‬\n\f      ‫يف الصــك املشــار إليــه يف الفقــرة األولــى مــن قــرار الدائــرة وتقريــره يف‬\n      ‫نفــس الصــك بــأن االتفاقيــة األخيــرة لــم تشــر إلــى املبلــغ املســلم وهــذا‬\n      ‫يــدل علــى أنــه مــن الثمــن مــا دام لــم يشــترط عــدم اعتبــاره وقــت العقــد‬\n      ‫والكتابــة يف شــيك املائتــي ألــف ريــال رقــم ‪ 147‬يف ‪1427/3/9‬ه ـ‬\n      ‫املســحوب علــى شــركة الراجحــي املصرفيــة بأنهــا دفعــت مــن قيمــة‬\n      ‫فلــة املنــار فعلــى فضيلتــه إعــادة النظــر وتقريــر مــا يظهــر لــه وإجــراء مــا‬\n      ‫يلــزم نحــوه وإحلــاق ملخــص مــا يجريــه يف الضبــط إلــى الصــك وســجله‬\n      ‫ومــن ثــم إعــادة املعاملــة حســب التعليمــات ‪ .‬وبــاهلل التوفيــق ) ا‪.‬ه ـ وجوابـ ًا‬\n      ‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول أنــه ســبق وأن أثبــت فضيلــة‬\n      ‫ســلفنا بالصــك الصــادر منــه برقــم ‪ 17/43‬وتاريــخ ‪1430/11/23‬ه ـ بأن‬\n      ‫مبلــغ املائتــي ألــف غيــر داخــل يف االتفاقيــة األخيــرة بعــد أن أدى املدعــي‬\n      ‫اليمــن علــى نفــي ذلــك بعــد طلــب املدعــى عليــه لهــا وعليــه فلــم يظهــر‬\n      ‫لــي مــا يوجــب العــدول عمــا حكمــت بــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n                                                                     ‫‪1433/12/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬ففــي يــوم الســبت ‪1433/02/09‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 45‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض وبرفقهــا القــرار رقــم ‪ 3410470‬وتاريــخ ‪1434/01/12‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم‪ .‬إ‪.‬ه ـ ‪ ،‬وللبيــان جــرى حتريــره ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪1434/02/09‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أن ‪ ...........‬القاضــي باحملكمــة العامــة بالريــاض يــوم االثنــن املوافــق‬\n\n\n‫‪103‬‬\n\f‫‪1434/05/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 9.45‬وفيهــا حضــر املدعــي‬\n‫‪ ........‬وأقــر باســتالم كامــل املبلــغ وقــدره مائتــا ألــف ريــال مســحوب‬\n‫علــى مصــرف الراجحــي بشــيك رقــم ‪ 252055‬وتاريــخ ‪1434/4/29‬ه ـ‬\n‫وتعتبــر القضيــة منتهيــة‪ .‬وبــاهلل التوفيــق‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/5/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعــت الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة لهــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بالريــاض املســاعد باخلطاب رقــم ‪332180983‬‬\n‫وتاريــخ ‪1434/01/03‬ه ـ املرفــق بهــا الصــك رقــم ‪ 33192371‬وتاريــخ‬\n‫‪1433/04/14‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ............ /‬املتضمــن‬\n‫احلكــم يف الدعــوى املقامــة مــن ‪ ............./‬ضــد ‪ ........ /‬والــذي ســبق‬\n‫أن لوحــظ عليــه بالقــرار رقــم‪ 33460003‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫وبدراســة مــا أجــراه فضيلتــه بعــد املالحظــة قــررت الدائــرة املصادقــة‬\n‫علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪104‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":97,"source_page_end":104,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c45b1daaf4cfa541b4e63a398c125cfc19fdb4523f6fc36cd4ee3c6fb96686a1","normalized_text_hash":"77830c36bdf2fec13591290076f4db417ca37e3f864ae1e8439cc5a7d98e0415","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p97-33192371"},{"id":"4a3d019d-1635-5262-9879-65bc7a197c8b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع تراب -عدم قبض كامل الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول -اليمن للمدعي -احلكم غيابي ا بتسليم باقي الثمن للمدعي -الغائب على حجته متى حضر .","document_number":"3304195","case_number":"41056","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/18","year":"1434","subject":"بيع -بيع تراب -عدم قبض كامل الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول -اليمن للمدعي -احلكم غيابي ا بتسليم باقي الثمن للمدعي -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/6/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3304195 :‬‬\n                            ‫َر ْق ُم الدعوى‪41056 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3425305‬تاريخه‪1434/1/28 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع تــراب ‪ -‬عــدم قبــض كامــل الثمــن ‪ -‬عــدم حضــور املدعــى‬\n      ‫عليــه ‪ -‬شــهادة الشــهود العــدول ‪ -‬اليمــن للمدعــي‪ -‬احلكــم غيابي ـ ًا‬\n         ‫بتســليم باقــي الثمــن للمدعــي‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم (لــو يعطــى النــاس بدعواهــم الدعــى نــاس‬\n                   ‫دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن الشــركة املدعــى عليهــا والغائبــة عــن املجلــس‬\n      ‫الشــرعي اتفقــت معــه علــى شــراء تــراب مــن مزرعتــه مبقابــل معــن‪ ،‬وقد‬\n      ‫قامــت الشــركة بتحميــل التــراب مقابــل مبلــغ معــن قامــت بســداد جــزء‬\n      ‫منــه ولــم تقــم بســداد الباقــي ‪ ،‬أحضــر املدعــي شــاهدين شــهدا بقيــام‬\n      ‫الشــركة بتحميــل تــراب مــن مزرعــة املدعــي‪ ،‬كمــا أن املدعــي أدى‬\n      ‫اليمــن الشــرعية علــى صحــة دعــواه ‪ -‬صــدر احلكــم بإلــزام الشــركة‬\n      ‫املدعــى عليهــا بدفــع املبلــغ املدعــى بــه والغائــب علــى حجتــه متــى حضــر‬\n                                   ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪105‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالريــاض برقــم ‪ 41056‬وتاريــخ ‪ 1431/09/11‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 31159750‬وتاريــخ ‪ 1431/09/05‬ه ـ يف‬\n‫يــوم الســبت املوافــق ‪ 1432/6/11‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة والربــع وكان الوقــت احملــدد لهــا هــو الســاعة العاشــرة وفيهــا‬\n‫حضــر ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪............‬‬\n‫ولــم حتضــر املدعــى عليهــا شــركة ‪ ..............‬وقــد وردتنــا ورقــة طلــب‬\n‫احلضــور مــن قســم احملضريــن برقــم ‪ 32441909‬يف ‪1432/4/25‬ه ـ‬\n‫وقــد تضمنــت توقيــع املدعــو ‪ ...........‬محاســب الشــركة املدعــى عليهــا‬\n‫بتبلــغ الشــركة املدعــى عليهــا مبوعــد هــذه اجللســة ‪ ،‬وبنــاء عليــه فقــد‬\n‫مت رفــع اجللســة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر مــن ميثــل‬\n‫املدعــى عليهــا شــركة ‪...........‬هــذا وقــد أبــرز املدعــي خطــاب شــرطة‬\n‫امللــز رقــم بــدون وتاريــخ ‪1433/1/22‬ه ـ املتضمــن تعــذر ابــاغ املدعــى‬\n‫عليهــا حســب احملضــر املرفــق مت طلبهــم للحضــور اكثــر مــن مــرة‬\n‫ولــم يحضــر لدينــا مــن قبلهــم احــد حتــى تاريخــه هــذا وبتصفــح اوراق‬\n‫املعاملــة وجــدت بــن طياتهــا ورقــة التبليــغ مبوعــد اجللســة احملــددة يف‬\n‫تاريــخ ‪1432/2/4‬ه ـ املوقعــة مــن قبــل ‪.............‬املديــر املالــي للشــركة‬\n‫وبنــاء عليــه فقــد اذنــت للمدعــي يف تقــدمي دعــواه فادعــى قائــا‪ :‬ادعــي‬\n‫علــى الغائــب عــن املجلــس الشــرعي شــركة ‪ ............‬بأننــي ســبق وان‬\n‫اتفقــت مــع املدعــى عليهــا بتاريــخ ‪2009/4/15‬م علــى شــراء املدعــى‬\n\n                                                                                   ‫‪106‬‬\n\f      ‫عليهــا لتــراب مــن مزرعتــي الواقعــة يف حائــل يف املوقــع ‪ ....‬مــن مســار‬\n      ‫ســكة احلديــد علــى شــكل ردود قالبيــات وان يكــون ســعر الــرد‬\n      ‫عشــرة ريــاالت وقــد قامــت الشــركة بتحميــل ردود بلغــت قيمتهــا مائــة‬\n      ‫وواحــد وتســعون ألــف وســتمائة ريــال متثــل قيمــة تســعة عشــر ألــف ومائــة‬\n      ‫وســتني رد قــاب وقــد ســلمتني الشــركة املدعــى عليهــا مــن هــذا املبلــغ‬\n      ‫عشــرة آالف ريــال وتبقــى يف ذمتهــا مبلغـ ًا وقدرهــا مائــة وواحــد وثمانــون‬\n      ‫ألفـ ًا وســتمائة ريــال أطلــب يف دعــواي هــذه احلكــم علــى املدعــى عليهــا‬\n      ‫بســداد هــذا املبلــغ هــذه دعــواي وبســؤاله هــل لديــه بينــة قــال‪ :‬نعــم‬\n      ‫ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد مت رفــع اجللســة‬\n      ‫‪ ،‬ثــم يف جلســة أخــرى حضــر املدعــي ‪ ................‬ولــم يحضــر مــن ميثــل‬\n      ‫الشــركة املدعــى عليهــا وقــد ســبق أن تقــدم املدعــي بطلــب اســتخالف‬\n      ‫محكمــة األجفــر بحائــل لســماع بينتــه وقــد جــرى منــي الكتابــة إلــى‬\n      ‫احملكمــة املذكــورة الســتخالف قاضــي احملكمــة يف ســماع شــهود‬\n      ‫املدعــي باخلطــاب رقــم ‪ 33/519547‬يف ‪1433/3/19‬ه ـ هــذا وقــد وردنا‬\n      ‫خطــاب مديــر شــرطة امللــز رقــم بــدون وتاريــخ ‪1433/3/9‬ه ـ املتضمــن‬\n      ‫أن صاحــب الشــركة غيــر متواجــد وقــد تبلــغ موظــف الشــركة بهــذا‬\n      ‫املوعــد وباالطــاع علــى طلــب احلضــور وجــد أنــه موقــع مــن قبــل ‪.........‬‬\n      ‫وقــال املدعــي إننــا حضرنــا لــدى قاضــي محكمــة األجفر وســمع شــهادة‬\n      ‫ـاء عليــه فقــد قــررت رفــع اجللســة إلــى حــن ورود اجلــواب ‪،‬‬   ‫شــهودي وبنـ ً‬\n      ‫ويف جلســة أخــرى حضــر ‪ ..............‬املدونــة هويتــه ســابقا ولــم يحضــر‬\n      ‫مــن ميثــل املدعــى عليهــا شــركة ‪ ....‬هــذا وقــد وردنــا خطــاب قاضــي‬\n      ‫احملكمــة العامــة باألجفــر رقــم ‪ 427‬يف ‪1433/4/7‬ه ـ املرفــق بــه صــورة‬\n      ‫الضبــط عــدد ‪ 5‬يف ‪1433/4/7‬ه ـ املتضمــن نــص احلاجــة منــه فقــد‬\n\n\n‫‪107‬‬\n\f‫حضــر ‪............‬املذكــور أعــاه وجــرى ســؤاله عــن بينتــه فقــال أحضــرت‬\n‫شــاهدين أطلــب ســماع شــهادتهما وأحضــر للشــهادة وأدائهــا ‪...........‬‬\n‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ..........‬واملولــود يف ‪1395/7/1‬ه ـ‬\n‫وبســؤاله عــن مهنتــه وجهــة اتصالــه باخلصــوم قــال ال أعمــل وال يوجــد‬\n‫بينــي وبــن املتداعيــن أي قرابــة إال أن املدعــي جــار لنــا يف املزرعــة يف‬\n‫قريــة ‪ ....‬التابعــة ملركــز ‪ ....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n‫هلل بــأن هنــاك قالبيــات وشــيوالت تابعــة للــ‪ ..........‬وهي شــركة ‪.............‬‬\n‫كانــت حتمــل مــن مزرعــة ‪ ................‬تــراب حتفــر الشــيوالت يف املزرعــة‬\n‫ثــم حتملهــا القالبيــات وهــي تضعهــا يف ســكة القطــار وكان بدايتهــم‬\n                                   ‫يف أوائــل عــام ‪1430‬ه ـ تقريبــا شــهر صفــر‬\n‫احلمــد هلل وحــده وبعــد ف ففــي يــوم الســبت املوافــق ‪ 1432/6/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــر والربــع وكان الوقــت احملــدد لهــا‬\n‫هــو الســاعة العاشــرة وفيهــا حضــر ‪ ...............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .................‬ولــم حتضــر املدعــى عليهــا شــركة‬\n‫‪ .............‬وقــد وردتنــا ورقــة طلــب احلضــور مــن قســم احملضريــن برقــم‬\n‫‪ 32441909‬يف ‪1432/4/25‬ه ـ وقــد تضمنــت توقيــع املدعــو ‪.............‬‬\n‫محاســب الشــركة املدعــى عليهــا بتبلــغ الشــركة املدعــى عليهــا مبوعد‬\n‫هــذه اجللســة ‪ ،‬وبنــاء عليــه فقــد مت رفــع اجللســة وحتــدد النظــر فيهــا يــوم‬\n‫األربعــاء املوافــق ‪1432/10/16‬ه ـ الســاعة العاشــرة والنصــف وقــررت‬\n‫الكتابــة إلــى قســم احملضريــن باحملكمــة إلبــاغ املدعى عليهــا باملوعد‬\n‫اآلخــر وبــه ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر والنصــف وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                               ‫يف ‪1432/6/11‬ه ـ‬\n\n\n                                                                                       ‫‪108‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1432/10/16‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 05‬وفيهــا حضــر املدعــي ولــم حتضــر‬\n      ‫املدعــى عليهــا وال مــن ينــوب عنهــا ولــم يــرد مــا يفيــد تبلــغ مــن ميثلهــا‬\n      ‫ومبــا أن املدعــى عليــه لــم يتبلــغ لشــخصه لــذا فقــد قــررت رفــع اجللســة‬\n      ‫وحتديــد موعــد آخــر وإبــاغ املدعــى عليــه بــه وحتــدد النظــر فيهــا يــوم‬\n      ‫الســبت بتاريــخ ‪1433/1/22‬ه ـ الســاعة التاســعة والنصــف وبــه ختمــت‬\n      ‫اجللســة يف متــام الســاعة ‪ 11:14‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1432/10/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم الســبت املوافــق ‪1433/1/22‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 10 : 07‬وكان الوقت احملدد لها هو الســاعة ‪09.30‬‬\n      ‫وفيهــا حضــر املدعــي ولــم يحضــر مــن ميثــل املدعــى عليهــا شــركة‬\n      ‫‪ ...........‬هــذا وقــد ابــرز املدعــي خطــاب شــرطة امللــز رقــم بــدون وتاريــخ‬\n      ‫‪1433/1/22‬ه ـ املتضمــن تعــذر إبــاغ املدعــى عليهــا حســب احملضــر‬\n      ‫املرفــق مت طلبهــم للحضــور اكثــر مــن مــرة ولــم يحضــر لدينــا مــن قبلهــم‬\n      ‫احــد حتــى تاريخــه هــذا وبتصفــح أوراق املعاملــة وجدت بــن طياتها ورقة‬\n      ‫التبليــغ مبوعــد اجللســة احملــددة يف تاريــخ ‪1432/2/4‬ه ـ املوقعــة من قبل‬\n      ‫‪ ..........‬املديــر املالــي للشــركة وبنــاء عليــه فقــد أذنــت للمدعــي يف تقــدمي‬\n      ‫دعــواه فادعــى قائــا‪ :‬ادعــي علــى الغائــب عــن املجلــس الشــرعي شــركة‬\n      ‫‪ ..........‬بأننــي ســبق وان اتفقــت مــع املدعــى عليهــا بتاريــخ ‪2009/4/15‬م‬\n      ‫علــى شــراء املدعــى عليهــا لتــراب مــن مزرعتــي الواقعــة يف حائــل يف‬\n      ‫املوقــع ‪ ....‬مــن مســار ســكة احلديــد علــى شــكل ردود قالبيــات وان‬\n      ‫يكــون ســعر الــرد عشــرة ريــاالت وقــد قامــت الشــركة بتحميــل ردود‬\n      ‫بلغــت قيمتهــا مائــة وواحــد وتســعون ألــف وســتمائة ريــال متثــل قيمــة‬\n\n\n‫‪109‬‬\n\f‫تســعة عشــر ألــف ومائــة وســتني رد قــاب وقــد ســلمتني الشــركة‬\n‫املدعــى عليهــا مــن هــذا املبلــغ عشــرة آالف ريــال وتبقــى يف ذمتهــا مبلغـ ًا‬\n‫وقدرهــا مائــة وواحــد وثمانــون ألفـ ًا وســتمائة ريــال أطلــب يف دعواي هذه‬\n‫احلكــم علــى املدعــى عليهمــا بســداد هــذا املبلــغ هــذه دعــواي وبســؤاله‬\n‫هــل لديــه بينــة قــال‪ :‬نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء‬\n‫عليــه فقــد مت رفــع اجللســة وقــررت إبــاغ املدعــى عليهــا باملوعــد القــادم‬\n‫وحتــدد النظــر فيهــا يــوم األحــد بتاريــخ ‪1433/4/11‬هـ الســاعة العاشــرة‬\n‫والنصــف وبــه ختمــت اجللســة يف متــام الســاعة ‪ 10:30‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪1432/1/22‬هـ‬\n‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق‪ 1433/04/11‬ه ـ افتتحــت‬\n‫اجللسة الساعة ‪ 11 : 11‬وفيها حضر املدعي ‪ ............‬ولم يحضر من ميثل‬\n‫الشــركة املدعــى عليهــا وقــد ســبق أن تقــدم املدعــي بطلــب اســتخالف‬\n‫محكمــة األجفــر بحائــل لســماع بينتــه وقــد جــرى منــي الكتابــة إلــى‬\n‫احملكمــة املذكــورة الســتخالف قاضــي احملكمــة يف ســماع شــهود‬\n‫املدعــي باخلطــاب رقــم ‪ 33/519547‬يف ‪1433/3/19‬ه ـ هــذا وقــد وردنا‬\n‫خطــاب مديــر شــرطة امللــز رقــم بــدون وتاريــخ ‪1433/3/9‬ه ـ املتضمــن‬\n‫أن صاحــب الشــركة غيــر متواجــد وقــد تبلــغ موظــف الشــركة بهــذا‬\n‫املوعــد وباالطــاع علــى طلــب احلضــور وجــد أنــه موقــع مــن قبــل ‪...........‬‬\n‫وقــال املدعــي إننــا حضرنــا لــدى قاضــي محكمــة األجفر وســمع شــهادة‬\n‫شــهودي وبنــاءا عليــه فقــد قــررت رفــع اجللســة إلــى حــن ورود اجلــواب‬\n‫وحتــدد النظــر فيهــا يــوم األثنــن املوافــق ‪1433/6/16‬هـ الســاعة ‪11.30‬‬\n‫وبــه ختمــت اجللســة الســاعة ‪ 11.25‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n\n\n                                                                                      ‫‪110‬‬\n\f           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/11‬ه ـ‬\n      ‫واســتمروا عشــرين يومــا علــى هــذا املنــوال ثــم توقفــوا تقريبــا اســبوعني‬\n      ‫إلــى ثالثــة ثــم رجعــوا للحفــر مــن مزرعتــه وحتميــل التــراب لفتــرة ال تقــل‬\n      ‫عن خمســة أشــهر علما أن ســكني شــرق مزرعة املذكور وهي ال تبعد‬\n      ‫عنــي أكثــر مــن نصــف كيلــو تقريبــا ونحــن نســمع إزعــاج الشــيوالت‬\n      ‫والقالبيــات ونراهــا أثنــاء دخولنــا ألن طريــق الشــيوالت والقالبيــات‬\n      ‫ال بــد أن ميــر علــى البيــت هــذا مــا أشــهد بــه كمــا أحضــر للشــهادة‬\n      ‫وأدائهــا ‪ .........‬ســعودي بالســجل املدنــي رقــم ‪ .................‬واملولــود بتاريــخ‬\n      ‫‪1398/7/1‬ه ـ وبســؤاله عــن مهنتــه وجهــة اتصالــه باخلصــوم قــال أنــا ال‬\n      ‫أعمــل رســمي إال أننــي مــؤذن جامــع ‪ ...‬وال يوجــد بينــي وبــن أي اخلصــوم‬\n      ‫أي قرابــة وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل بــأن شــخص‬\n      ‫‪ ...........‬نســيت اســمه قد اتفق مع ‪ .............‬على حتميل تراب من مزرعة‬\n      ‫‪ ..............‬وكتبــوا العقــد لدينــا يف البيــت وبعدهــا رأيناهــم يحفــرون مــن‬\n      ‫مزرعــة ‪ ........‬ويحملــون يف القالبيــات وميــرون يف طريقهــم علــى بيتنــا‬\n      ‫وأزعجونــا ليــا ونهــارا حتــى طلبنــا منهــم أن يتحولــوا إلــى طريــق آخــر‬\n      ‫وأنــا مــؤذن اجلامــع ومكثــي دائمــا يف قريــة ‪ ...‬وأراهــم علمــا أن املســافة‬\n      ‫بــن بيتنــا ومزرعــة ‪ .......‬ال تصــل إلــى كيلــو متــر بــل أقــل وحملــوا أوال‬\n      ‫عشــرين يومــا ثــم توقفــوا ثــم اكملــوا احلفــر ألكثــر مــن خمســة أشــهر‬\n      ‫وأمــا عــن وقــت حفرهــم فــا أذكــر بالضبــط قبــل ســنة ونصــف أو أقــل‬\n      ‫أو أكثــر هــذا مــا أشــهد بــه كمــا حضــر كل مــن ‪ ............‬ســعودي‬\n      ‫اجلنســية بالســجل املدنــي رقــم ‪..............‬و‪ ...........‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم ‪ ...............‬اللذيــن شــهدا بــأن الشــاهدين مــن أهــل‬\n      ‫الصــاح والصــاة ولــم يعرفــا عنهمــا الكــذب هــذا مــا قــاال وعليــه فقــد‬\n\n\n‫‪111‬‬\n\f‫جــرى إثباتــه أه ـ وبســؤال املدعــي هــل لديــه زيــادة بينــة أبــرز صــورة عقــد‬\n‫شــراء علــى مطبوعــات شــركة ‪ ..........‬الطــرف األول شــركة ‪............‬‬\n‫وميثلهــا ‪ .........‬الطــرف الثانــي ‪ ..............‬وتضمــن العقــد شــراء تــراب مــن‬\n‫املزرعــة التابــع للثانــي علــى شــكل ردود وتضمــن يف الفقــرة الثالثــة‬\n‫ســعر الــرد الواحــدة ثالثــة ريــال ويكــون ســعر الــرد عشــرة ريــاالت‬\n‫اعتبــارا مــن ‪2009/5/9‬م كمــا وجــدت بــن طيــات املعاملــة خطــاب مــن‬\n‫‪ ..............‬موجــه لشــرطة امللــز يفيــد أن حســاب املدعــي لــدى شــركة‬\n‫‪ ............‬وليــس لديــه شــخصيا فجــرى ســؤال املدعــي هــل لديــه زيــادة‬\n‫بينــة قــال ال ليــس لــدي إال مــا قدمــت وأســتعد بــأداء اليمــن فقــال يف‬\n‫هــذا املجلــس واهلل العظيــم إننــي اتفقــت مــع املدعــى عليهــا شــركة‬\n‫‪...........‬علــى حتميــل تــراب مــن مزرعتــي بســعر الــرد عشــر ريــاالت وأنــه‬\n‫اســتحق يف ذمتهــم مبلغــا قــدره مائــة وواحــد وثمانــون ألفــا وســتمائة ريــال‬\n‫وبنــاء علــى مــا ســبق مــن الدعــوى واالجابــة ولقولــه صلــى اهلل عليــه وســلم‬\n‫لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن‬\n‫اليمــن علــى املدعــى عليــه ومبــا أن املدعــي قــدم شــاهديه املعدلــن‬\n‫شــرعا واللذيــن شــهدا بقيــام املدعــى عليهــا بتحميــل تــراب مــن مزرعــة‬\n‫املدعــي ومبــا ان املدعــي أدى اليمــن الشــرعية علــى صحــة دعــواه ومبــا‬\n‫أن الشــركة املدعــى عليــه قــد تبلــغ مديرهــا بهــذه الدعــوى لذلــك كلــه‬\n‫فقــد حكمــت علــى املدعــى عليــه شــركة ‪ ..............‬غيابيــا بــأن تســلم‬\n‫للمدعــي املبلــغ املدعــى بــه والــذي قــدره مائــة وواحــد وثمانــون ألفــا‬\n‫وســتمائة ريــال واملدعــى عليــه علــى حجتــه متــى مــا حضــر وبعرضــه علــى‬\n‫املدعــي قنــع بــه وقــررت بعــث صــورة مــن نســخة احلكــم للمدعــى عليهــا‬\n‫وإفهامهــم بــأن لهــم مهلــة ثالثــن يــوم مــن تاريــخ االســتالم لتقــدمي الئحتهم‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫االعتراضيــة فــإذا انتهــت املهلــة ولــم يتقدمــوا بالئحتهــم االعتراضيــة‬\n      ‫ســقط حقهــم باالعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة‬\n      ‫الســاعة ‪ 1.15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/02/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 9:15‬وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 34164381‬يف ‪1434/2/10‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n      ‫رقــم ‪ 3425305‬يف ‪1434/1/28‬ه ـ واملتضمــن وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم‬\n      ‫واهلل املوفــق أه ـ ‪ ،‬وعليــه جــرى تهميــش مبوجبــه ‪ ،‬وبــه ختمــت اجللســة‬\n      ‫يف متــام الســاعة ‪ 09:20‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/27‬ه ـ ‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":105,"source_page_end":113,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"999729b8476aa152572a0690762dae6218fb18b76fc3a1d94e8999c1e37dabee","normalized_text_hash":"99409da72ffb37901d4043a2af056df6fed935660a10cd43fe8603cf3cbf3a03","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p105-3304195"},{"id":"0b400ab5-f73b-5a37-807f-0f2bd12012ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -شراء املدعى عليه سيارة -كفالة غرم وأداء للمدعى عليه -سداد املدعى عليه جزء من ثمن السيارة -مطالبة البائع املدعي (الكفيل) بسداد باقي الثمن -سداد املدعي كامل الثمن مبوجب صك -للكفيل حق الرجوع على مكفوله فيما غرمه عنه -احلكم غيابي ا بإلزام املدعى عليه بدفع املبلغ املدعى به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"3410373","case_number":"47263","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة احلقوقية اخلامسة رقم 34169008وتاريخ 1434/2/23ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"بيع -شراء املدعى عليه سيارة -كفالة غرم وأداء للمدعى عليه -سداد املدعى عليه جزء من ثمن السيارة -مطالبة البائع املدعي (الكفيل) بسداد باقي الثمن -سداد املدعي كامل الثمن مبوجب صك -للكفيل حق الرجوع على مكفوله فيما غرمه عنه -احلكم غيابي ا بإلزام املدعى عليه بدفع املبلغ املدعى به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410373 :‬‬\n                      ‫َر ْق ُم الدعوى‪47263 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34169008‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬شــراء املدعــى عليــه ســيارة ‪ -‬كفالــة غــرم وأداء للمدعــى عليــه‬\n‫‪ -‬ســداد املدعــى عليــه جــزء مــن ثمــن الســيارة ‪ -‬مطالبــة البائــع املدعــي‬\n‫(الكفيــل) بســداد باقــي الثمــن ‪ -‬ســداد املدعــي كامــل الثمــن مبوجــب‬\n‫صــك ‪ -‬للكفيــل حــق الرجــوع علــى مكفولــه فيمــا غرمــه عنــه ‪ -‬احلكــم‬\n‫غيابي ـ ًا بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ -‬الغائــب علــى‬\n‫حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                                                      ‫املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n‫‪( -‬ويرجــع الضامــن وكل مــن أدى عــن غيــره دينــا واجبــا بنيــة الرجــوع)‬\n                                                ‫يف كشــاف القناع (‪. )372/3‬‬\n                            ‫‪ -‬املادة (‪176 ، 55‬من نظام املرافعات الشرعية) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلــه ســبق أن كفــل املدعــى عليه كفالة‬\n‫غــرم وأداء يف ثمــن ســيارة ‪ ،‬ســدد املدعــى عليــه جــزء مــن ثمنهــا وامتنــع‬\n‫ـاء علــى صــك‬ ‫عــن ســداد الباقــي ‪ ،‬قــام املدعــي بســداد باقــي الثمــن بنـ ً‬\n‫يلزمــه بالســداد ‪ ،‬مت تبليــغ املدعــى عليــه بالدعــوى إال أنــه لــم يحضــر‪،‬‬\n‫وملــا كانــت القاعــدة أن للكفيــل حــق الرجــوع علــى مكفولــه فيمــا‬\n\n                                                                                     ‫‪114‬‬\n\f      ‫غرمــه عنــه حكمــت احملكمــة غيابيـ ًا بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n      ‫املدعــى بــه للمدعــي أصالــة ‪ -‬مت رفــع احلكــم حملكمــة االســتئناف‬\n      ‫لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n      ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض برقــم ‪ 47263‬وتاريــخ ‪ 1431/11/09‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 31185780‬وتاريــخ ‪ 1431/11/09‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1432/02/07‬ه ـ حضــر املدعــي وكالــة ‪.............‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ ............‬بصفتــه وكيــا عــن ‪...........‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...........‬مبوجــب صــك وكالــة صــادر‬\n      ‫مــن كتابــة العــدل الثانيــة يف جيــزان برقــم ‪ 8975‬يف ‪1431/11/1‬ه ـ‬\n      ‫ولــم يحضــر املدعــى عليــه ‪.................‬وعــاد إلينــا خطــاب التبليــغ رقــم‬\n      ‫‪ 32/123012‬يف ‪1431/11/9‬ه ـ وقــد دون عليــه محضــر اخلصوم رفض‬\n      ‫املوظــف املختــص اســتالم البــاغ لكــون املدعــى عليه يتواجــد يف الدوام‬\n      ‫املســائي‪ .‬ويف يــوم الســبت املوافــق ‪1432/5/12‬ه ـ حضر املدعي وكالة‬\n      ‫‪ ...............‬املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه‬\n      ‫‪ ............‬وعــاد إلينــا خطــاب التبليــغ املــؤرخ يف ‪1432/2/7‬ه ـ وقــد دون‬\n      ‫عليــه محضــر اخلصــوم رفــض املوظــف املختــص اســتالم البــاغ والتوقيــع‬\n      ‫وذلــك بعــد االتصــال علــى املدعــى عليــه فقــال املوظــف ال تســتلم البــاغ ‪.‬‬\n      ‫ويف يــوم األربعــاء املوافق‪1433/03/30‬ه ـ حضــر املدعــي وكالــة ‪..........‬‬\n      ‫املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه ‪ .........‬ووردنــا‬\n‫‪115‬‬\n\f‫جــواب مديــر مركــز شــرطة امللــز رقــم ‪ 1451‬وتاريــخ ‪1433/2/6‬ه ـ‬\n‫املتضمــن االتصــال باملدعــى عليــه بواســطة اجلــوال وأفــاد أنــه يف جيــزان‬\n‫وبنــاء علــى تبلــغ املدعــى عليــه مرتــن وعــدم جتاوبــه باســتالم التبليــغ‬\n‫وبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات جــرى ســماع الدعــوى غيابيــا‬\n‫وبســؤال املدعــي عــن دعــواه أجــاب قائــا‪ :‬ســبق أن كفــل موكلــي‬\n‫املدعــى عليــه كفالــة غــرم وأداء يف ثمــن ســيارة هايلوكــس غمارتــن‬\n‫موديــل ‪2000‬م اشــتراها املدعــى عليــه مــن ‪ ...............‬يف عــام ‪1421‬ه ـ‬\n‫بثمــن قــدره تســعون ألــف ريــال مقســطة كل شــهر ألــف وخمســمائة‬\n‫ريــال اعتبــارا مــن ‪1421/5/30‬ه ـ وســدد املدعــى عليــه مــن ثمنهــا تســعة‬\n‫آالف وســتمائة ريــال فقــط وبقــي مــن ثمنهــا ســبعون ألــف وأربعمائــة‬\n‫ريــال حــل منهــا أربعــة وخمســون ألــف ريــال ولــم يســددها للبائــع فأقــام‬\n‫البائــع دعــواه ضــد موكلــي لســداد باقــي الثمــن وصــدر مــن محكمــة‬\n‫محافــظ أبــو عريــش الصــك رقــم ‪ 3/6‬وتاريــخ ‪1425/1/9‬ه ـ بإلــزام‬\n‫موكلــي بســداد ذلــك املبلــغ للبائــع املذكــور وســدد موكلــي ذلــك املبلــغ‬\n‫أربعــة وخمســن ألــف وأربعمائــة ريــال ثــم املدعــى عليــه لــم يســدد للبائــع‬\n‫باقــي املبلــغ بعــد ذلــك احلكــم وقــدره ســتة عشــر ألــف ريــال فســددها‬\n‫موكلــي للبائــع بعــد ان طالبــه بهــا لــذا أطلــب إلــزام املدعــى عليــه أن‬\n‫يســدد ملوكلــي املبلــغ الــذي ســدده عنــه ســبعني ألــف وأربعمائــة ريــال‬\n‫هــذه دعــواي وبســؤاله عــن بينــة أبــرز صــورة الصــك املشــار إليــه أعــاه‬\n‫املتضمــن مــا ذكــره مــن الدعــوى ضــد موكلــه واحلكــم عليــه مببلــغ‬\n‫أربعمائــة وخمســن ألــف وأربعمائــة ريــال ثــم همــش عليــه بتســلم املدعــى‬\n‫عليــه ذلــك املبلــغ املدعــى بــه للبائــع وبســؤال املدعــي وكالــة عــن أصــل‬\n‫الصــك اســتعد بإحضــاره كمــا أبرز صورة ورقــة على مطبوعات ‪...........‬‬\n\n\n                                                                                     ‫‪116‬‬\n\f      ‫لبيــع وشــراء الســيارات املــؤرخ يف ‪1431/7/14‬ه ـ ونصــه بعــد املقدمــة ما‬\n      ‫يلــي‪ :‬تشــهد مؤسســة ‪ ..............‬بــأن املدعــو ‪ ..........................‬قــد حكــم‬\n      ‫بالصــك رقــم ‪ 3/6‬يف ‪1425/1/9‬ه ـ مببلــغ وقــدره أربعــة وخمســون ألــف‬\n      ‫وأربعمائــة ريــال وقــام بدفــع املبلــغ املــدون يف ‪ 54400‬وقــام بدفــع باقــي‬\n      ‫املبلــغ وبذلــك يكــون املبلــغ املدفــوع مــن قبــل املدعــو ‪........................‬‬\n      ‫‪ 70400‬ســبعون ألــف وأربعمائــة وقــد أعطــي هــذا املشــهد ختــم املؤسســة‬\n      ‫مــع توقيــع‪ .‬أه ـ وأمــرت بالكتابــة إلــى محكمــة أبوعريــش لتزويدنــا‬\n      ‫بصــورة طبــق األصــل مــن صــك احلكــم املشــار إليــه أعــاه واســتخالف‬\n      ‫احملكمــة إلحضــار ‪.............‬وســؤاله عمــا يدعيــه املدعــي مــن ســداده‬\n                                                       ‫للمبلــغ حســب مــا جــاء يف املشــهد‪.‬‬\n      ‫ويف يــوم االثنــن املوافق‪1434/01/12‬ه ـ حضــر املدعي وكالــة ‪............‬‬\n      ‫املــدون هويتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه ‪...............‬‬\n      ‫ووردنــا جــواب القائــم بعمــل رئيــس احملكمــة العامــة مبحافظــة أبــو‬\n      ‫عريــش املكلــف برقــم ‪ 3/1383/3405‬وتاريــخ ‪1433/8/26‬ه ـ‬\n      ‫وبرفقــه صــورة طبــق األصــل مــن مكتــب القضائــي رقــم ‪ 3‬وهــذا نصــه‬\n      ‫بعــد املقدمــة حضــر املدعــي وكالــة ‪ ..............‬ســعودي مبوجــب ســجل‬\n      ‫مدنــي رقــم (‪ )............‬مبوجــب الوكالــة رقــم ‪ 29‬وتاريخ ‪1432/2/15‬هـ‬\n      ‫الصــادرة مــن كتابــة عــدل أبــو عريــش والتــي تخولــه حــق اإلقــرار وأقــر‬\n      ‫بقولــه‪ :‬إن موكلــي اســتلم كامــل املبلــغ املطالــب فيــه يف القضيــة‬\n      ‫الصــادر بهــا الصــك رقــم ‪ 3/6‬وتاريــخ ‪1425/1/9‬ه ـ الصــادر مــن‬\n      ‫محكمــة أبــو عريــش كمــا أن موكلــي ال يطالــب املدعــى عليــه بــأي‬\n      ‫مبلــغ بهــذه البيعــة مطلقــا علمــا بــأن املبلــغ ســبعون ألــف ريــال هكــذا‬\n      ‫قــرر‪ .‬أه ـ ومبــا أن املدعــي وكالــة ذكــر يف دعــواه أن موكلــه ســدد‬\n\n\n‫‪117‬‬\n\f‫ســبعني ألفـ ًا وأربعمائــة ريــال بينمــا جــاء يف الضبــط أعــاه حتديــد املبلــغ‬\n‫بســبعني ألــف ريــال أجــاب قائــا‪ :‬اقصــر دعــواي علــى املطالبــة مببلــغ‬\n‫ســبعني ألــف ريــال هكــذا قــرر ولــم يتــم مــن قبــل محكمــة أبــو عريــش‬\n‫إرفــاق صــورة طبــق األصــل مــن صــك احلكــم ‪ 3/6‬فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى وعــدم حضــور املدعــى عليــه ومــا أبــرزه املدعــي وكالــة‬\n‫مــن الصــك رقــم ‪ 3/6‬واســتخالفنا محكمــة أبــو عريــش وورود جوابهــم‬\n‫وبرفقــه صــورة ضبــط تضمنــت إقــرار احملكــوم لــه وكالــة باســتالم‬\n‫املبلــغ احملكــوم بــه ومبــا أن للكفيــل حــق الرجــوع علــى مكفولــه فيمــا‬\n‫غرمــه عنــه كمــا قــرره الفقهــاء قــال يف كشــاف القنــاع (‪:)372/3‬‬\n‫ويرجــع الضامــن وكل مــن أدى عــن غيــره دينــا واجبــا بنيــة الرجوع‪.‬أه ـ‬\n‫وقصــر املدعــي وكالــة دعــواه علــى مبلــغ ســبعني ألــف ريــال لــذا فقــد‬\n‫ألزمــت املدعــى عليــه الغائــب أن يدفــع للمدعــي أصالــة املبلــغ املدعــى‬\n‫بــه وقــدره ســبعون ألــف ريــال والغائــب علــى حجتــه متــى حضــر وبــه‬\n‫حكمــت وأمــرت إخــراج صــك مبوجبــه وإبــاغ احملكــوم عليــه بصورتــه‬\n‫لتقريــر قناعتــه أو معارضتــه وتقــدمي الئحــة اعتراضــه خــال ثالثــن‬\n‫يومــا فــإن مضــت مــدة االعتــراض ولــم يقــدم الئحــة اعتراضــه بعــد تبلغــه‬\n‫ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪1434/01/12‬هــ‪ .‬ويف يــوم االثنــن املوافق‪1434/02/25‬ه ـ افتتحــت‬\n‫اجللســة الســاعة بنــاء علــى شــرح رئيــس احملكمــة العامــة بالريــاض‬\n‫املســاعد علــى القيــد رقــم ‪ 34380999‬وتاريــخ ‪1434/02/16‬ه ـ وبرفقــه‬\n‫خطــاب مديــر مركــز شــرطة الفيصليــة واخلالديــة رقــم ‪12/6/961/2‬‬\n‫وتاريــخ ‪1434/02/12‬ه ـ بشــأن تســليم صــك احلكــم للمحكــوم عليــه‬\n\n\n                                                                                      ‫‪118‬‬\n\f      ‫‪ .............‬واملتضمــن إعــادة األوراق لعــدم معرفــة املدعــي وكالــة عنــوان‬\n      ‫املدعــى عليــه‪ .‬وبنــاء علــى تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى‬\n      ‫احملكــوم عليــه وبنــاء علــى املــادة ‪ 5/176‬مــن نظــام املرافعــات الشــرعية‬\n      ‫والئحتــه التنفيذيــة أمــرت بإحلاقــه علــى صكــه وســجله ورفــع احلكــم‬\n      ‫بدون الئحة اعتراض مع كامل ملف الدعوى إلى محكمة االستئناف‬\n      ‫بالريــاض لتدقيقــه‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/04/03‬ه ـ افتتحــت‬\n      ‫اجللســة بنــاء علــى ورود خطــاب رئيــس محكمــة االســتئناف بالريــاض‬\n      ‫املكلــف رقــم ‪ 34638402‬وتاريــخ ‪1434/3/28‬ه ـ وبرفقــه قــرار‬\n      ‫الدائــرة احلقوقيــة اخلامســة رقــم ‪ 34169008‬وتاريــخ ‪1434/2/23‬ه ـ‬\n      ‫املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم مــع تنبيــه‬\n      ‫فضيلتــه لتصحيــح مــا حتتــه خــط مــن مبلــغ‪ .‬وبــاهلل التوفيــق وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 31185780‬وتاريخ ‪1434/3/4‬هـ املرفق بها الصك الصادر من فضيلة‬\n      ‫القاضــي باحملكمــة الشــيخ‪ ................./‬املســجل برقــم ‪3410373‬‬\n      ‫وتاريــخ ‪1434/1/12‬ه ـ اخلــاص بدعوى‪............./‬وكالــة ضــد‪............/‬‬\n      ‫يف مبلــغ مــن املــال علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم‬\n      ‫فضيلتــه كمــا هــو موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم مــع تنبيــه‬\n      ‫فضيلتــه لتصحيــح مــا حتتــه خــط مــن مبلــغ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                            ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":114,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b61ce1a3295472344f6c1a52e382c96504dc5f877c35fb0888376582d6d0198","normalized_text_hash":"dcd6368af04ad7db1047063f6d5a380ed218c16b6066c6e2d75c50fc4bc92a45","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p114-3410373"},{"id":"e4fdb79c-7851-5261-af26-bb7ddad2f5e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة بأقساط -شرط حلول كامل الثمن حال تأخر املدين عن دفع ثالثة أقساط -بينة املدعي -حلف اليمن -عدم حضور املدعى عليه -احلكم غيابي ا بدفع كامل األقساط - الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","document_number":"33251132","case_number":"339922","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/17","year":"1434","subject":"بيع -بيع سيارة بأقساط -شرط حلول كامل الثمن حال تأخر املدين عن دفع ثالثة أقساط -بينة املدعي -حلف اليمن -عدم حضور املدعى عليه -احلكم غيابي ا بدفع كامل األقساط - الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33251132 :‬‬\n                     ‫َر ْق ُم الدعوى‪339922 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34262550‬تاريخه‪1434/7/9 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة بأقســاط ‪ -‬شــرط حلــول كامــل الثمــن حــال تأخــر‬\n‫املديــن عــن دفــع ثالثــة أقســاط‪ -‬بينــة املدعــي ‪ -‬حلــف اليمــن‪ -‬عــدم‬\n‫حضــور املدعــى عليــه ‪ -‬احلكــم غيابي ـ ًا بدفــع كامــل األقســاط ‪-‬‬\n‫الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة االســتئناف‬\n                                         ‫لتعــذر تبليــغ املدعــى عليــه ‪.‬‬\n\n\n\n\n‫‪ -1‬قــرار املجمــع الفقهــي ( صحــة شــرط مــن تأخــر عــن قســط مــن‬\n                                      ‫األقســاط فيحــل املبلــغ كامــا )‬\n‫‪ -2‬مــا ذكــره املجــد أبــو البــركات رحمــه اهلل يف محــرره بقولــه ( ومــن‬\n‫أدعــى علــى غائــب أو مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه‬\n       ‫بينــة ســمعت وحكــم لــه ويســتحلفه احلاكــم علــى بقــاء حقــه )‪.‬‬\n                             ‫‪ -3‬املادة ( ‪ ) 55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫بــاع املدعــي ســيارة للمدعــى عليــه مبوجــب عقــد‪ ،‬مت النــص يف العقــد‬\n‫علــى دفــع كامــل الثمــن حــال تأخــر املدعــى عليــه عــن دفــع ثالثــة‬\n‫أقســاط‪ ،‬قــدم املدعــي لصحــة دعــواه إقــرار املدعــى عليــه كتابــة مبــا‬\n\n                                                                                ‫‪124‬‬\n\f      ‫ســبق‪ ،‬حلــف املدعــي اليمــن علــى صحــة دعــواه‪ ،‬لــم يحضــر املدعــى‬\n      ‫عليــه‪ ،‬صــدر احلكــم غيابي ـ ًا بدفــع كامــل األقســاط املتبقيــة ‪ -‬رفــع‬\n      ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪-‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n      ‫فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة بتبــوك وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك‪/‬‬\n      ‫املســاعد برقــم ‪ 339922‬وتاريخ‪1433/1/3‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 3324540‬وتاريخ‪1433/1/3‬ه ـ حضــر ‪ ...........‬ســعودي اجلنســية‬\n      ‫ا عــن ‪................‬‬\n                            ‫مبوجــب الســجل املدنــي رقــم‪ ...........‬بصفتــه وكي ـ ً‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل بخميــس مشــيط برقــم‬\n      ‫‪ 770711000289‬وتاريــخ ‪1433/1/8‬ه ـ واملخــول لــه فيهــا حــق املرافعــة‬\n      ‫واملخاصمــة واملدافعــة وحضــور اجللســات ‪ ،‬ولــم يحضــر املدعــى عليــه‬\n      ‫رغــم تبلغــه باملوعــد لشــخصه مبوجــب اإلفــادة الصــادرة مــن مجموعــة‬\n      ‫الشــرطة العســكرية اخلاصــة الثالثــة برقــم ‪ 6054/27/16/3‬وتاريــخ‬\n      ‫‪1433/3/9‬ه ـ ونصهــا نفيدكــم بأنــه مت إبــاغ املدعــى عليــه وتوقيعــه‬\n      ‫علــى اســتالم صــورة لتبليــغ أ‪.‬ه ـ ‪ ،‬وبســؤال املدعــي عــن دعــواه قــرر‬\n      ‫ا لقــد بــاع موكلــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم‬   ‫قائـ ً‬\n      ‫‪ ........................‬ســيارة نــوع ‪ .....‬موديــل ‪ 2008‬رقــم اللوحــة أوراق‬\n      ‫جمركيــة بتاريــخ ‪ 1431/1/12‬بقيمــة إجماليــة قدرهــا أربعــون الــف‬\n      ‫ريــال علــى هيئــة أقســاط شــهرية قــدر كل قســط ألــف ريــال اعتبــار ًا‬\n\n‫‪125‬‬\n\f‫مــن ‪1431/1/25‬ه ـ وقــد أشــترط موكلــي عليــه أنــه يف حالــة تأخــره‬\n‫ا ومــن ذلــك التاريــخ‬  ‫بدفــع ثالثــة أقســاط فــإن املبلــغ حــال الدفــع كامـ ً‬\n‫لــم يصــل موكلــي منهــا شــيئ ًا حتــى اآلن أطلــب إلزامــه بدفــع املبلــغ هــذه‬\n‫دعــواي وبســؤاله البينــة قــال أحضرهــا يف اجللســة القادمــة عليــه رفعــت‬\n‫اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر املدعــى‬\n‫عليــه رغــم تبلغــه باملوعــد لشــخصه مبوجــب اإلفــادة الصــادرة مــن‬\n‫مجموعــة الشــرطة العســكرية اخلاصــة الثالثــة برقــم ‪8127/27/16/3‬‬\n‫وتاريــخ ‪1433/4/3‬ه ـ ونــص املفيــد منــه نفيدكــم بأنــه مت إبــاغ املدعــى‬\n‫عليــه وتوقيعــه علــى اســتالم صــورة التبليــغ أ‪.‬ه ـ ‪ ،‬ولــم يردنــا منــه أي عذر‬\n‫وبســؤال املدعــي وكالــة عــن البينــة قــدم لنــا الورقــة اآلتــي نصهــا أقــر أنــا‬\n‫املوقــع أســمي أدنــاه ‪ ..................‬بأننــي اشــتريت ســيارة نــوع ‪ 2008 ....‬من‬\n‫األخ ‪ ..............‬مببلــغ وقــدره أربعــون ألــف ريــال على هيئة أقســاط شــهرية‬\n‫مقــدار القســط ألــف ريــال اعتبــار ًا مــن ‪1431/1/25‬ه ـ كمــا ال يحق لي‬\n‫تأخيــر أي قســط وإذا تأخــرت ثالثــة أقســاط متتاليــة فإنــي مســتعد بدفع‬\n‫كامــل املبلــغ وعليــه أوقــع املقــر مبــا فيــه ‪ ................‬توقيعــه بصمتــه أ‪.‬ه ـ‬\n‫‪ ،‬ونظــر ًا النتهــاء وقــت اجللســة فقــد رفعــت ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة ‪ ................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ..........‬ولــم يحضــر املدعــى عليــه وبعــرض اليمــن علــى املدعــي أصالــة‬\n‫ا واهلل أن دعــواي ضــد املدعــى عليــه‬            ‫اســتعد بأدائ ــها ثــم حلــف قائ ـ ً‬\n‫‪ ...........‬صحيحــة وأن لــي بذمتــه مبلــغ أربعــن ألــف ريــال حــال الدفــع‬\n‫لــم يصل ــني منــه شــيء ح ــتى اآلن هك ــذا ح ــلف فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى ولكــون املدعــى عليــه تبلــغ لشــخصه ولــم يحضــر ولــم يردنــا‬\n‫ـاء علــى البينــة واليمــن املســتظهرة واســتنادا علــى املــادة‬        ‫منــه عــذر وبنـ ً‬\n\n                                                                                              ‫‪126‬‬\n\f      ‫اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية وملــا ذكــره املجــد‬\n      ‫أبــو البــركات رحمــه اهلل يف محــرره بقولــه ومــن أدعــى علــى غائــب أو‬\n      ‫مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه بينــة ســمعت وحكــم‬\n      ‫لــه ويســتحلفه احلاكــم علــى بقــاء حقــه وملــا تقــدم ذكــره فقــد حكمــت‬\n      ‫علــى املدعــى عليــه ‪ ...........‬أن يســلم للمدعــي ‪ .........‬مبلــغ أربعــن ألــف‬\n      ‫ريـ(‪ )40000‬ــال وقــررت الكتابــة للمدعــى عليــه ألخــذ قناعتــه باحلكــم‬\n      ‫مــن عدمهــا وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                             ‫حــرر يف ‪1433/5/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق‪ 1433/10/22‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 01 : 00‬وكان قــد جــرى منــا الكتابــة ملديــر قســم‬\n      ‫احملضريــن باحملكمــة لتســليم املدعــى عليــه ‪ ...............‬نســخة احلكــم‬\n      ‫لتقــدمي الئحتــه االعتراضيــة مبوجــب كتابنــا رقــم ‪ 33945061‬وتاريــخ‬\n      ‫‪1433/5/26‬ه ـ وحيــث وردنــا اجلــواب مــن قائــد مجموعــة الشــرطة‬\n      ‫العســكرية اخلاصــة الثالثــة مبوجــب كتابــة رقــم ‪19437/27/16/3‬‬\n      ‫وتاريــخ ‪1433/8/24‬ه ـ ونــص املفيــد منــه نفيدكــم بــأن املذكــور‬\n      ‫صــدر لــه قــرار إنهــاء خدمــات مبوجــب القــرار املرفــق رقــم ‪46413‬‬\n      ‫وتاريــخ ‪1433/8/17‬ه ـ اعتبــارا ً مــن تاريــخ ‪1433/5/15‬ه ـ نأمــل العلــم‬\n      ‫واإلحاطــة أ ‪ .‬ه ـ ‪ ،‬وملــا ذكــر واســتناد ًا علــى الفقــرة اخلامســة مــن املــادة‬\n      ‫السادســة والســبعني بعــد املائــة ونصهــا إذا تعــذر تســليم نســخة احلكــم‬\n      ‫الغيابــي إلــى احملكــوم عليــه أو وكيلــه رفــع احلكــم إلــى محكمــة‬\n      ‫التمييــز بــدون الئحــة اعتراضيــة ‪ ،‬وال مينــع مــن ذلــك التمــاس إعــادة‬\n      ‫النظــر وفــق أحكامــه أ ‪.‬ه ـ ‪ ،‬عليــه فقــد قــررت إحالتهــا إلــى محكمــة‬\n      ‫االســتئناف مبنطقــة تبــوك لتدقيقــه وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n\n\n‫‪127‬‬\n\f                             ‫آلــه وصحبــه وســلم حــرر يف ‪1433/10/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد يف يوم الســبت املوافــق‪ 1434/06/10‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي وكالــة ‪...............‬‬\n‫وقــد أحضــر وكالــة جديــدة تتضمــن الرقــم ‪ 570709003205‬يف‬\n‫‪1433/2/17‬ه ـ صــادرة مــن كتابــة العــدل بخميــس مشــيط واملخــول لــه‬\n‫فيهــا حــق اإلقــرار واملرافعــة واملدافعــة ‪ ،‬وكانــت املعاملــة قــد عــادت مــن‬\n‫محكمــة االســتئناف مبنطقــة تبــوك مبوجــب كتــاب فضيلــة رئيســها‬\n‫رقــم ‪ 3462953‬وتاريــخ ‪1434/2/6‬ه ـ ونــص املفيــد منــه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي‪ -1 :‬بعثت املعاملة‬\n‫إلــى محكمــة االســتئناف قبــل اكتمــال إجــراءات تبليــغ احملكــوم‬\n‫عليــه بنســخة احلكــم ‪ -2 .‬مــن أنــواع الشــروط يف عقــد البيــع شــرط‬\n‫فاســد ينــايف مقتضــي العقــد ويصــح معــه البيــع كمــا قــرره أهــل العلــم‬\n‫يف موضعــه لقــول الرســول صلــى اهلل عليــه وســلم((من اشــترط شــرط ًا‬\n‫ليــس يف كتــاب اهلل فهــو باطــل وإن كان مائــة شــرط)) متفــق عليــه‬\n‫وتراضــي الطرفــن علــى هــذا الشــرط ال يصححــه وهــذا ينطبــق علــى‬\n‫الشــرط املذكــور يف العقــد محــل النــزاع ولــذا صــدرت فتــوى اللجنــة‬\n‫الدائمــة لإلفتــاء برئاســة ســماحة الشــيخ ابــن بــاز رحمــه اهلل بأنــه شــرط‬\n‫غيــر صحيــح ألنــه ينفــي مقتضــى العقــد وهــو التأجيــل التــي اســتحقت‬\n‫بــه الزيــادة أ‪.‬ه ـ مجمــوع فتــاوي اللجنــة الدائمــة ‪ 182/13‬واملناســب‬\n‫يف هــذه القضيــة وأمثالهــا أن يحكــم باملبلــغ احلــال بحســب األقســاط‬\n‫كمــا يحكــم بدفــع بقيــة األقســاط يف موعــد حلولهــا حســب مــا جــاء يف‬\n‫العقــد بينهــا‪ .‬فنرغــب إطــاع فضيلــة وتأملــه يف ذلــك واتخــاذ مــا يظهــر‬\n‫لــه وفقــه اهلل وإعــادة املعاملــة إلينــا بعــد ذلــك وبــاهلل التوفيــق ‪ .‬وبعــرض‬\n\n\n                                                                                        ‫‪128‬‬\n\f      ‫املالحظــة الثانيــة علــى املدعــي وكالــة قــال بــأن جميــع املبلــغ قــد حــل‬\n      ‫يف ذمــة املدعــى عليــه ملوكلــي وكان قــد جــرى منــا الكتابــة لشــرطة‬\n      ‫منطقــة تبــوك لإلفــادة عــن عنــوان املدعــى عليــه وحيــث وردنــا اجلــواب‬\n      ‫منهــم مبوجــب كتابهــم رقــم ‪ 13/2292/28‬وتاريــخ ‪1434/5/28‬ه ـ‬\n      ‫ونــص املفيــد منــه نفيــد فضيلتكــم بأنــه مت البحــث عــن املواطــن‬\n      ‫‪ ............‬وأتضــح أنــه يســكن محافظــة صامطــة التابعــة ملنطقــة جيــزان‬\n      ‫أ‪.‬ه ـ ‪ ،‬وبعرضــه أيضــا ً علــى املدعــي وكالــة قــال مــا جــاء يف كتــاب‬\n      ‫مديــر شــرطة منطقــة تبــوك صحيــح ولكنــه أثنــاء إقامــة الدعــوى كان‬\n      ‫املدعــى عليــه يســكن تبــوك وهــو مــا زال يســكنها إال أنــه يتهــرب‬\n      ‫عــن احلضــور وحســبي اهلل ونعــم الوكيــل ‪ ،‬كمــا أحيــط أصحــاب‬\n      ‫الفضيلــة ‪ -‬ســلمهم اهلل ‪ -‬بأنــه ال زيــادة مقابــل التأجيــل بحيــث ينطبــق‬\n      ‫مــا ذكــر وإمنــا هــي مســالة اشــتراط البائــع باألصــل حلــول األقســاط‬\n      ‫قبــل موعدهــا عنــد تأخــر املدعــي عــن اداء بعضهــا مــادام املديــن قــد‬\n      ‫رضــي بهــذا الشــرط عنــد التعاقــد وهــذا مــا نــص علــى جــوزاه يف مجمــع‬\n      ‫الفقــه اإلســامي يف دورتــه املنعقــدة يف مؤمتــره الســادس مبحافظــة‬\n      ‫جــده باململكــة العربيــة الســعودية وعليــه فقــد قــررت إعــادة كامــل‬\n      ‫أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة تبــوك لتدقيقــه وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                               ‫يف ‪1434/6/10‬ه ـ ‪.‬‬\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34262550‬وتاريــخ‬\n                                                        ‫‪1434/7/9‬هـ‪.‬‬\n\n\n\n‫‪129‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":124,"source_page_end":129,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32ccc814a52f4aa00b2ea5c2b04301cfc897e5d72b0f8a1dc2705ae1a3956e7c","normalized_text_hash":"e123609dae23244c2d014bda4ad5b57c7a71b55060a2b7df5207212cc56883cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p124-33251132"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
